// Graphics managers.

/// `void PS2GraphicsMan_ResetTextureSlots(this, flags)` (0x37c7c0): clear the
/// 0x1f40-byte particle slot array at `+0x3838` and pass `flags` to the
/// texture allocator.
pub fn ps2_graphics_man_reset_texture_slots(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 18;
        let frame = Frame::open(c, 0x30);
        c.g[A2][0] = 0x1f40;
        frame.save(c, S0, 0x20);
        frame.save(c, S1, 0x10);
        c.g[S0][0] = c.g[A0][0];
        c.g[S1][0] = c.g[A1][0];
        frame.save_ra(c, 0);
        c.g[A0][0] = sx((c.g[S0][0] as u32).wrapping_add(0x3838));
        c.g[A1][0] = 0;
        call_ptr(c, 0x003e_6448, 0x0037_c7e8)?;
        c.g[A0][0] = Addr((c.g[S0][0] as u32).wrapping_add(0x18f4)).lw(c);
        c.g[A1][0] = c.g[S1][0];
        TEX_MAN_SET_ALLOC_FLAGS_2.call(c, 0x0037_c7f4)?;
        frame.restore(c, S0, 0x20);
        frame.restore(c, S1, 0x10);
        frame.restore_ra(c, 0);
        frame.close(c);
        Ok(())
    })
}

/// `void PS2GraphicsMan_RemoveInterruptHandlers(this)` (0x389118): detach the
/// two interrupt/DMA handlers registered for the graphics manager.
pub fn ps2_graphics_man_remove_interrupt_handlers(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 18;
        let frame = Frame::open(c, 0x20);
        frame.save(c, S0, 0x10);
        c.g[S0][0] = c.g[A0][0];
        frame.save_ra(c, 0);
        c.g[A0][0] = 0x2;
        call_ptr(c, 0x0042_4880, 0x0038_9130)?;
        c.g[A1][0] = Addr((c.g[S0][0] as u32).wrapping_add(0x5ac0)).lw(c);
        c.g[A0][0] = 0x2;
        call_ptr(c, 0x0042_3aa0, 0x0038_913c)?;
        c.g[A0][0] = 0x1;
        call_ptr(c, 0x0042_4950, 0x0038_9144)?;
        c.g[A1][0] = Addr((c.g[S0][0] as u32).wrapping_add(0x5ac4)).lw(c);
        c.g[A0][0] = 0;
        call_ptr(c, 0x0042_3ad0, 0x0038_9150)?;
        frame.restore(c, S0, 0x10);
        frame.restore_ra(c, 0);
        frame.close(c);
        Ok(())
    })
}

// ---------------------------------------------------------------------------
// Emitter teardown.

/// `void mEmitter_dtor(mEmitter* self, int flags)` (0x3714f8): install the
/// class vtable at +0x1f8, release the emitter's data and destroy the
/// dynamic-emitter base. 19 cycles plus the callees.
pub fn memitter_dtor(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 19;
        let frame = Frame::open(c, 0x30);
        c.g[V0][0] = sx(0x0049_30d0);
        frame.save(c, S0, 0x20);
        frame.save(c, S1, 0x10);
        let self_ = r32(c, A0);
        c.g[S0][0] = c.g[A0][0];
        frame.save_ra(c, 0);
        c.g[S1][0] = c.g[A1][0];
        c.sw(p(self_, 0x1f8), c.g[V0][0]);
        c.g[A1][0] = 0;
        callee::MEMITTER_FREE_DATA.call(c, 0x0037_1524)?;
        c.g[A0][0] = c.g[S0][0];
        c.g[A1][0] = c.g[S1][0];
        callee::DYNAMIC_EMITTER_DTOR.call(c, 0x0037_1530)?;
        frame.restore(c, 16, 0x20);
        frame.restore(c, 17, 0x10);
        frame.restore_ra(c, 0);
        frame.close(c);
        Ok(())
    })
}

/// `void PS2GraphicsMan_SetBrightnessAlpha(void* self, float a)`
/// (0x37c720): store the brightness ramp for `1 - clamp(a, 1)`, scaled to
/// 128 steps.
pub fn ps2_graphics_man_set_brightness_alpha(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 9;
        c.mtc1(0, 0); // f0 = 0
        let frame = Frame::open(c, 0x20);
        frame.save(c, S0, 0x10);
        c.c_le_s(0, 12); // 0 <= a
        frame.save_ra(c, 0);
        c.g[AT][0] = 0x3f80_0000; // 1.0
        c.mtc1(1, 1);
        let below = !c.fcc();
        let this = r32(c, A0);
        c.g[S0][0] = c.g[A0][0];
        if !below {
            c.cycles += 1;
            c.min_s(0, 12, 1);
        }
        c.cycles += 10;
        c.sub_s(0, 1, 0); // 1 - clamp
        c.g[AT][0] = 0x4300_0000; // 128.0
        c.mtc1(1, 12);
        c.g[RA][0] = sx(0x0037_c75c);
        c.mul_s(12, 0, 12);
        call_ptr(c, 0x0041_39f8, 0x0037_c75c)?;
        Addr(p(this, 0x59f8)).sw(c, c.g[V0][0]);
        frame.restore(c, S0, 0x10);
        frame.restore_ra(c, 0);
        frame.close(c);
        Ok(())
    })
}

/// `void BoaderShadow_AllocTexture(BoaderShadow* s)` (0x375990): if the
/// texture handle at `+0x170` is negative (not yet allocated), allocate it
/// through the graphics manager's `v52` with the stored size/format.
pub fn boader_shadow_alloc_texture(c: &mut Cpu) {
    c.cycles += 7;
    let frame = Frame::open(c, 0x20);
    frame.save(c, S0, 0x10);
    frame.save_ra(c, 0);
    c.g[S0][0] = c.g[A0][0];
    c.g[V0][0] = Addr(p_3(c, S0, 0x170)).lw(c);
    if (c.g[V0][0] as i64) < 0 {
        c.cycles += 11;
        c.g[T0][0] = Addr(gp_3(c, 0x2a90)).lw(c);
        c.g[A3][0] = 2;
        c.g[A1][0] = Addr(p_3(c, S0, 0x174)).lw(c);
        c.g[V1][0] = Addr(p_3(c, T0, 0x10d8)).lw(c);
        c.g[A2][0] = Addr(p_3(c, S0, 0x178)).lw(c);
        c.g[A0][0] = Addr(p_3(c, V1, 0x1a0)).lh(c);
        c.g[V0][0] = Addr(p_3(c, V1, 0x1a4)).lw(c);
        let target = abi::r32(c, V0);
        c.g[A0][0] = sx((c.g[T0][0] as u32).wrapping_add(c.g[A0][0] as u32));
        if call_ptr(c, target, 0x0037_59d0).is_err() {
            return;
        }
        c.sw(p_3(c, S0, 0x170), c.g[V0][0]);
    }
    c.cycles += 3;
    frame.restore(c, S0, 0x10);
    frame.restore_ra(c, 0);
    frame.close(c);
}

/// `addu reg, delta`: a vtable's adjusted `this`.
#[inline(always)]
pub(crate) fn this_with_delta(obj: u64, delta: u64) -> u64 {
    abi::addu(obj, delta)
}

/// `void* PS2GraphicsMan_SelectMatchingDisplayMode(PS2GraphicsMan* self)`
/// (0x376468): pick the first display mode the platform accepts, else 0.
pub fn ps2_graphics_man_select_matching_display_mode(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 11;
        let frame = Frame::open(c, 0x20);
        frame.save(c, S0, 0x10);
        frame.save_ra(c, 0);
        let this = r32(c, A0);
        c.g[S0][0] = c.g[A0][0];
        c.g[V1][0] = Addr(this).off(0x10d8).lw(c);
        c.g[A0][0] = Addr(r32(c, V1)).off(0x3d8).lh(c);
        c.g[V0][0] = Addr(r32(c, V1)).off(0x3dc).lw(c);
        let target = r32(c, V0);
        c.g[RA][0] = sx(0x0037_648c);
        c.g[A0][0] = this_with_delta(c.g[S0][0], c.g[A0][0]);
        call_ptr(c, target, 0x0037_648c)?;
        if (c.g[V0][0] as i64) < 0 {
            c.cycles += 2;
            c.g[V0][0] = 0;
        } else {
            c.g[V1][0] = Addr(r32(c, S0)).off(0x10d8).lw(c);
            c.cycles += 5;
            c.g[A1][0] = c.g[V0][0];
            c.g[A0][0] = Addr(r32(c, V1)).off(0x20).lh(c);
            c.g[V0][0] = Addr(r32(c, V1)).off(0x24).lw(c);
            let target = r32(c, V0);
            c.g[RA][0] = sx(0x0037_64b0);
            c.g[A0][0] = this_with_delta(c.g[S0][0], c.g[A0][0]);
            call_ptr(c, target, 0x0037_64b0)?;
        }
        c.cycles += 4;
        frame.restore(c, S0, 0x10);
        frame.restore_ra(c, 0);
        frame.close(c);
        Ok(())
    })
}

/// `int PS2GraphicsMan_LoadTexture(self, a1, a2, a3, a4, a5, a6, a7)`
/// (0x37caf8): forward to the texture manager and mark the returned slot used.
pub fn ps2_graphics_man_load_texture(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 22;
        let frame = Frame::open(c, 0x40);
        frame.save(c, S0, 0x30);
        frame.save_ra(c, 0x20);
        c.g[S0][0] = c.g[A0][0];
        c.g[V1][0] = Addr(frame.at(c, 0x48)).lw(c);
        c.g[V0][0] = Addr(frame.at(c, 0x40)).lw(c);
        c.g[T4][0] = Addr(frame.at(c, 0x50)).lw(c);
        c.g[T5][0] = Addr(frame.at(c, 0x58)).lw(c);
        c.g[A0][0] = Addr(r32(c, S0)).off(0x18f4).lw(c);
        Addr(frame.at(c, 0x8)).sw(c, c.g[V1][0]);
        Addr(frame.at(c, 0)).sw(c, c.g[V0][0]);
        Addr(frame.at(c, 0x10)).sw(c, c.g[T4][0]);
        c.g[RA][0] = sx(0x0037_cb30);
        Addr(frame.at(c, 0x18)).sw(c, c.g[T5][0]);
        callee::TEX_MAN_LOAD_TEXTURE.call(c, 0x0037_cb30)?;
        c.g[V1][0] = sx(r32(c, V0) << 2);
        c.g[A0][0] = 1;
        c.g[S0][0] = sx(r32(c, S0).wrapping_add(r32(c, V1)));
        frame.restore_ra(c, 0x20);
        Addr(r32(c, S0)).off(0x3838).sw(c, c.g[A0][0]);
        frame.restore(c, S0, 0x30);
        frame.close(c);
        Ok(())
    })
}

/// `void PS2GraphicsMan_EmitModelMatrix2(PS2GraphicsMan* self, Quad** pp,
/// const Matrix* m)` (0x37e040): append a model-matrix packet to the
/// graphics packet stream.
pub fn ps2_graphics_man_emit_model_matrix2(c: &mut Cpu) {
    c.cycles += 22;
    c.g[V0][0] = Addr(r32(c, A1)).lw(c);
    c.por(3, 0, 0);
    c.g[V1][0] = 0x1000_0000;
    c.g[V1][0] |= 0x5;
    c.g[A2][0] = 0x6c04_0000;
    c.g[A2][0] |= 0x8005;
    c.g[A2][0] <<= 32;
    c.sq(3, r32(c, V0));
    c.g[A3][0] = sx(r32(c, V0).wrapping_add(0x20));
    c.sd(p(r32(c, V0), 0x18), c.g[A2][0]);
    c.sd(p(r32(c, V0), 0x10), 0);
    c.lqc2(1, r32(c, A0));
    c.lqc2(2, p(r32(c, A0), 0x10));
    c.lqc2(3, p(r32(c, A0), 0x20));
    c.lqc2(4, p(r32(c, A0), 0x30));
    c.sqc2(1, r32(c, A3));
    c.sqc2(2, p(r32(c, A3), 0x10));
    c.sqc2(3, p(r32(c, A3), 0x20));
    c.sqc2(4, p(r32(c, A3), 0x30));
    c.g[V0][0] = sx(r32(c, V0).wrapping_add(0x60));
    c.sw(r32(c, A1), c.g[V0][0]);
    abi::ret(c);
}

/// `void PS2GraphicsMan_OnVif1DmaEnd(PS2GraphicsMan* self)` (0x382688): run
/// the DMA-end state machine (start, finish or idle).
pub fn ps2_graphics_man_on_vif1_dma_end(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 7;
        let frame = Frame::open(c, 0x10);
        c.g[A1][0] = c.g[A0][0];
        frame.save_ra(c, 0);
        c.g[V1][0] = 1;
        c.g[V0][0] = Addr(r32(c, A1)).off(0x5a8c).lw(c);
        let idle = c.g[V0][0] != c.g[V1][0];
        c.g[V0][0] = 2;
        if !idle {
            c.cycles += 6;
            c.g[A0][0] = Addr(r32(c, A1)).off(0x5ac8).lw(c);
            Addr(r32(c, A1)).off(0x5a8c).sw(c, c.g[V0][0]);
            c.g[RA][0] = sx(0x0038_26b4);
            call_ptr(c, callee::ISIGNAL_SEMA, 0x0038_26b4)?;
            frame.restore_ra(c, 0);
            c.cycles += 2;
            frame.close(c);
            return Ok(());
        }
        c.cycles += 4;
        c.g[V1][0] = Addr(r32(c, A1)).off(0x5a8c).lw(c);
        c.g[V0][0] = 3;
        let not_running = c.g[V1][0] != c.g[V0][0];
        frame.restore_ra(c, 0);
        if !not_running {
            c.cycles += 3;
            c.g[V0][0] = 4;
            Addr(r32(c, A1)).off(0x5a8c).sw(c, c.g[V0][0]);
            frame.restore_ra(c, 0);
        }
        c.cycles += 2;
        frame.close(c);
        Ok(())
    })
}

/// `PS2GraphicsMan` fields.
pub(crate) const GM_DISPLAY_MODE: u32 = 0x10dc;

pub(crate) const GM_VIEWPORTS: u32 = 0x6d20;

pub(crate) const GM_VIEWPORT_STRIDE: u32 = 0x230;

pub(crate) const GM_FOV: u32 = 0x6d38;

pub(crate) const GM_FOG_MODE: u32 = 0x6b94;

pub(crate) const GM_FOG_NEAR: u32 = 0x6b98;

pub(crate) const GM_FOG_FAR: u32 = 0x6b9c;

pub(crate) const GM_FOG_COLOR_A: u32 = 0x6ba0;

pub(crate) const GM_FOG_COLOR_B: u32 = 0x6ba4;

pub(crate) const GM_TEXTURES: u32 = 0x18f4;

pub(crate) const GM_LIGHTS: u32 = 0x13ec;

pub(crate) const GM_LIGHT_STRIDE: u32 = 0xa0;

pub(crate) const GM_VIEW_MATRICES: u32 = 0x6af0;

pub(crate) const GM_VIEW_ENTRIES: u32 = 0x5930;

pub(crate) const GM_VIEW_PAIRS: u32 = 0x59b0;

pub(crate) const GM_VIEW_PAIR_SRC: u32 = 0x5900;

pub(crate) const GM_VIEW_COUNT: u32 = 0x59c0;

pub(crate) const GM_PHASE2_TEX: u32 = 0x1440;

pub(crate) const GM_PHASE2_VTX: u32 = 0x1400;

pub(crate) const GM_PHASE2_Q: u32 = 0x13f0;

pub(crate) const GM_PHASE2_F: u32 = 0x1480;

pub(crate) const GM_PHASE2_I: u32 = 0x1484;

/// `lui at, bits; mtc1 at, f` — a float constant through `at`.
#[inline(always)]
pub(crate) fn fconst_2(c: &mut Cpu, f: usize, bits: u32) {
    c.g[AT][0] = bits as u64;
    c.f[f] = bits;
}

// ---------------------------------------------------------------------------
// Graphics manager.

/// `PS2GraphicsMan_GetDisplayModeInfo` (0x00376560): the display-mode record
/// for mode `idx` (0xa4 bytes each) after the pointer at `+0x59cc`.
pub fn ps2_graphics_man_get_display_mode_info(c: &mut Cpu) {
    c.cycles += 5;
    let gm = abi::arg(c, 0);
    let _idx = abi::arg(c, 1);
    c.g[V1][0] = 0xa4;
    c.g[V0][0] = c.lw(p(gm, 0x59cc));
    c.mult(0, A1, A1, V1);
    c.g[V0][0] = add32(c.g[V0][0], c.g[A1][0]);
    abi::ret(c);
}

/// `PS2GraphicsMan_GetViewport` (0x00376b90): copy viewport `mode`'s four
/// floats (0x230-byte records at `+0x6d20`) to `out` as integers converted
/// back to floats. The manager is `a1` and `out` is `a0`, as the original
/// reads them.
pub fn ps2_graphics_man_get_viewport(c: &mut Cpu) {
    c.cycles += 31;
    let out = abi::arg(c, 0);
    let gm = abi::arg(c, 1);
    c.g[V1][0] = c.lw(p(gm, GM_DISPLAY_MODE));
    c.g[A2][0] = GM_VIEWPORT_STRIDE as u64;
    c.g[V0][0] = c.g[A0][0];
    c.mult(0, V1, V1, A2);
    c.g[V1][0] = add32(c.g[V1][0], GM_VIEWPORTS as u64);
    c.g[A1][0] = add32(gm as u64, c.g[V1][0]);
    let vp = r(c, A1);
    c.lwc1(0, p(vp, 0xc));
    c.lwc1(2, vp);
    c.cvt_w_s(1, 0);
    c.mfc1(7, 1);
    c.lwc1(3, p(vp, 4));
    c.lwc1(1, p(vp, 8));
    c.cvt_w_s(0, 2);
    c.mfc1(3, 0);
    c.cvt_w_s(0, 3);
    c.mfc1(5, 0);
    c.cvt_w_s(0, 1);
    c.mfc1(6, 0);
    c.mtc1(3, 0);
    c.cvt_s_w(0, 0);
    c.mtc1(5, 1);
    c.cvt_s_w(1, 1);
    c.mtc1(6, 2);
    c.cvt_s_w(2, 2);
    c.mtc1(7, 3);
    c.cvt_s_w(3, 3);
    c.swc1(0, out);
    c.swc1(1, p(out, 4));
    c.swc1(2, p(out, 8));
    c.swc1(3, p(out, 0xc));
    abi::ret(c);
}

/// `PS2GraphicsMan_GetFov` (0x00376c10): the field of view of the current
/// display mode (float at `+0x6d38` of its viewport record), returned in `f0`.
pub fn ps2_graphics_man_get_fov(c: &mut Cpu) {
    c.cycles += 6;
    let gm = abi::arg(c, 0);
    c.g[V0][0] = c.lw(p(gm, GM_DISPLAY_MODE));
    c.g[V1][0] = GM_VIEWPORT_STRIDE as u64;
    c.mult(0, A1, V0, V1);
    c.g[V0][0] = add32(c.g[A1][0], c.g[A0][0]);
    c.lwc1(0, p(r(c, V0), GM_FOV));
    abi::ret(c);
}

/// `PS2GraphicsMan_GetNearFarAspect` (0x00376c28): the z/x/y of display mode
/// `mode`'s near/far/aspect record into `a`, `b`, `c`.
pub fn ps2_graphics_man_get_near_far_aspect(c: &mut Cpu) {
    c.cycles += 12;
    let gm = abi::arg(c, 0);
    let (out_a, out_b, out_c) = (abi::arg(c, 1), abi::arg(c, 2), abi::arg(c, 3));
    c.g[V0][0] = c.lw(p(gm, GM_DISPLAY_MODE));
    c.g[V1][0] = GM_VIEWPORT_STRIDE as u64;
    c.mult(0, V0, V0, V1);
    c.g[V0][0] = add32(c.g[V0][0], GM_VIEWPORTS as u64);
    c.g[A0][0] = add32(gm as u64, c.g[V0][0]);
    let rp = r(c, A0);
    c.lwc1(0, p(rp, 0x18));
    c.swc1(0, out_a);
    c.lwc1(1, p(rp, 0x10));
    c.swc1(1, out_b);
    c.lwc1(0, p(rp, 0x14));
    c.swc1(0, out_c);
    abi::ret(c);
}

/// `PS2GraphicsMan_SetFogMode` (0x00377950): store the fog mode and set its
/// three fog colour scales/offsets. Modes 1 and 2 have their own triples;
/// mode 0 and everything else falls back to the default white.
pub fn ps2_graphics_man_set_fog_mode(c: &mut Cpu) {
    c.cycles += 3;
    let gm = abi::arg(c, 0);
    let mode = abi::arg64(c, 1);
    c.g[V0][0] = 1;
    let is_one = mode == c.g[V0][0];
    c.sw(p(gm, GM_FOG_MODE), mode);
    if is_one {
        // Mode 1: 0.125 towards 0.75.
        c.cycles += 7;
        fconst_2(c, 0, 0x3f40_0000);
        fconst_2(c, 1, 0x3e00_0000);
        c.swc1(0, p(gm, GM_FOG_COLOR_B));
        c.swc1(1, p(gm, GM_FOG_NEAR));
        c.cycles += 3;
        c.swc1(0, p(gm, GM_FOG_FAR));
        c.swc1(0, p(gm, GM_FOG_COLOR_A));
        abi::ret(c);
        return;
    }
    c.cycles += 3;
    c.g[V0][0] = ((mode as i64) < 2i64) as u64;
    if c.g[V0][0] == 0 {
        c.g[V0][0] = 2;
        c.cycles += 2;
        if mode == c.g[V0][0] {
            // Mode 2: near 0, far/alpha 1, 0.75 in the colour slot.
            c.cycles += 9;
            fconst_2(c, 1, 0x3f80_0000);
            fconst_2(c, 0, 0x3f40_0000);
            c.swc1(1, p(gm, GM_FOG_COLOR_B));
            c.swc1(0, p(gm, GM_FOG_COLOR_A));
            c.sw(p(gm, GM_FOG_NEAR), 0);
            c.swc1(1, p(gm, GM_FOG_FAR));
            abi::ret(c);
            return;
        }
        c.cycles += 2;
        abi::ret(c);
        return;
    }
    c.cycles += 2;
    if mode == 0 {
        c.sw(p(gm, GM_FOG_NEAR), 0);
        c.cycles += 3;
        fconst_2(c, 0, 0x3f80_0000);
        c.swc1(0, p(gm, GM_FOG_COLOR_B));
        c.cycles += 3;
        c.swc1(0, p(gm, GM_FOG_FAR));
        c.swc1(0, p(gm, GM_FOG_COLOR_A));
        abi::ret(c);
        return;
    }
    c.cycles += 2;
    abi::ret(c);
}

/// `PS2GraphicsMan_SetFogParams` (0x003779e0): `*(self + 0x6b94) = *src`
/// (20 bytes: the fog record).
pub fn ps2_graphics_man_set_fog_params(c: &mut Cpu) {
    c.cycles += 12;
    let gm = abi::arg(c, 0);
    let src = abi::arg(c, 1);
    c.ldl(2, p(src, 7));
    c.ldr(2, src);
    c.ldl(3, p(src, 0xf));
    c.ldr(3, p(src, 8));
    c.g[A2][0] = c.lw(p(src, 0x10));
    c.sdl(2, p(gm, GM_FOG_MODE + 7));
    c.sdr(2, p(gm, GM_FOG_MODE));
    c.sdl(3, p(gm, GM_FOG_MODE + 0xf));
    c.sdr(3, p(gm, GM_FOG_MODE + 8));
    c.sw(p(gm, GM_FOG_MODE + 0x10), c.g[A2][0]);
    abi::ret(c);
}

/// `PS2GraphicsMan_IsTextureValid` (0x0037cb90): negative indices are always
/// valid (the default texture); indices past 1999 are not; otherwise the
/// table entry must be non-null.
pub fn ps2_graphics_man_is_texture_valid(c: &mut Cpu) {
    c.cycles += 2;
    let gm = abi::arg(c, 0);
    let idx = abi::arg64(c, 1);
    let negative = (idx as i64) < 0;
    c.g[V1][0] = c.lw(p(gm, GM_TEXTURES));
    if negative {
        c.cycles += 2;
        c.g[V0][0] = 1;
        abi::ret(c);
        return;
    }
    c.cycles += 3;
    c.g[V0][0] = ((idx as i64) < 2000i64) as u64;
    let in_range = c.g[V0][0] != 0;
    c.g[V0][0] = sx((idx as u32) << 2);
    if !in_range {
        c.cycles += 2;
        c.g[V0][0] = 0;
        abi::ret(c);
        return;
    }
    c.cycles += 4;
    c.g[V0][0] = sx((c.g[V1][0] as u32).wrapping_add(c.g[V0][0] as u32));
    c.g[V1][0] = c.lw(p(r(c, V0), 8));
    c.g[V0][0] = (0u64 < c.g[V1][0]) as u64;
    abi::ret(c);
}

/// `PS2GraphicsMan_AddLight` (0x0037d758): append a light (quad, two
/// matrices, a float, an int) to the table at `+0x13ec`/`+0x13f0`.
pub fn ps2_graphics_man_add_light(c: &mut Cpu) {
    c.cycles += 42;
    let gm = abi::arg(c, 0);
    let quad = abi::arg(c, 1);
    let m0 = abi::arg(c, 2);
    let m1 = abi::arg(c, 3);
    c.g[V1][0] = c.lw(p(gm, GM_LIGHTS));
    c.g[T2][0] = GM_LIGHT_STRIDE as u64;
    c.lq(9, quad);
    c.mult(0, V0, V1, T2);
    c.g[V1][0] = add32(c.g[V0][0], gm as u64);
    c.sq(9, p(r(c, V1), GM_PHASE2_Q));
    c.g[V0][0] = c.lw(p(gm, GM_LIGHTS));
    c.mult(0, V1, V0, T2);
    c.g[V0][0] = add32(c.g[V1][0], gm as u64);
    c.g[V0][0] = sx((c.g[V0][0] as u32).wrapping_add(GM_PHASE2_VTX));
    c.lqc2(1, m0);
    c.lqc2(2, p(m0, 0x10));
    c.lqc2(3, p(m0, 0x20));
    c.lqc2(4, p(m0, 0x30));
    let vtx = r(c, V0);
    c.sqc2(1, vtx);
    c.sqc2(2, p(vtx, 0x10));
    c.sqc2(3, p(vtx, 0x20));
    c.sqc2(4, p(vtx, 0x30));
    c.g[V1][0] = c.lw(p(gm, GM_LIGHTS));
    c.mult(0, V0, V1, T2);
    c.g[V1][0] = add32(c.g[V0][0], gm as u64);
    c.g[V1][0] = sx((c.g[V1][0] as u32).wrapping_add(GM_PHASE2_TEX));
    c.lqc2(1, m1);
    c.lqc2(2, p(m1, 0x10));
    c.lqc2(3, p(m1, 0x20));
    c.lqc2(4, p(m1, 0x30));
    let tex = r(c, V1);
    c.sqc2(1, tex);
    c.sqc2(2, p(tex, 0x10));
    c.sqc2(3, p(tex, 0x20));
    c.sqc2(4, p(tex, 0x30));
    c.g[V0][0] = c.lw(p(gm, GM_LIGHTS));
    c.mult(0, V1, V0, T2);
    c.g[V0][0] = add32(c.g[V1][0], gm as u64);
    c.swc1(12, p(r(c, V0), GM_PHASE2_F));
    c.g[V1][0] = c.lw(p(gm, GM_LIGHTS));
    c.mult(0, V0, V1, T2);
    c.g[V1][0] = add32(c.g[V0][0], gm as u64);
    c.sw(p(r(c, V1), GM_PHASE2_I), c.g[T0][0]);
    c.g[V0][0] = c.lw(p(gm, GM_LIGHTS));
    c.g[V0][0] = sx((c.g[V0][0] as u32).wrapping_add(1));
    c.sw(p(gm, GM_LIGHTS), c.g[V0][0]);
    abi::ret(c);
}

/// The `tex0` T-bit field (`>> shift, & 0xf`) of texture `idx`, as
/// `1 << field`: the texture's width/height in pixels.
pub(crate) fn texture_size(c: &mut Cpu, shift: u32) {
    c.cycles += 12;
    let gm = abi::arg(c, 0);
    let idx = abi::arg(c, 1);
    c.g[V0][0] = c.lw(p(gm, GM_TEXTURES));
    c.g[A1][0] = sx((idx as u32) << 2);
    c.g[A0][0] = 1;
    c.g[V0][0] = sx((c.g[V0][0] as u32).wrapping_add(c.g[A1][0] as u32));
    c.g[V1][0] = c.lw(p(r(c, V0), 8));
    c.g[V0][0] = c.ld(p(r(c, V1), 0x38));
    c.g[V0][0] >>= shift;
    c.g[V0][0] &= 0xf;
    c.g[V0][0] <<= 32;
    c.g[V0][0] = ((c.g[V0][0] as i64) >> 32) as u64;
    c.g[V0][0] = sx((c.g[A0][0] as u32) << ((c.g[V0][0] as u32) & 31));
    abi::ret(c);
}

/// `PS2GraphicsMan_GetTextureWidth` (0x0037d908): the width (`tex0.TW`) of
/// texture `idx`.
pub fn ps2_graphics_man_get_texture_width(c: &mut Cpu) {
    texture_size(c, 26);
}

/// `PS2GraphicsMan_GetTextureHeight` (0x0037d938): the height
/// (`tex0.TH`) of texture `idx`.
pub fn ps2_graphics_man_get_texture_height(c: &mut Cpu) {
    texture_size(c, 30);
}

/// `PS2GraphicsMan_ClipTestBox` (0x0037de88): run the VU0 box-clip
/// microprogram at `D_570 >> 3` on the two points (`a1`, `a2`) and the clip
/// matrix (`a3`), then report 1 for the far side, 2 for the near side, 0 for
/// "no clip".
pub fn ps2_graphics_man_clip_test_box(c: &mut Cpu) {
    c.cycles += 18;
    let a = abi::arg(c, 1);
    let b = abi::arg(c, 2);
    let m = abi::arg(c, 3);
    c.g[V0][0] = 0;
    c.g[V0][0] = sx((c.g[V0][0] as u32).wrapping_add(0x570));
    c.g[V0][0] = sx((c.g[V0][0] as u32) >> 3);
    c.lqc2(15, a);
    c.lqc2(16, b);
    c.lqc2(10, m);
    c.lqc2(11, p(m, 0x10));
    c.lqc2(12, p(m, 0x20));
    c.lqc2(13, p(m, 0x30));
    c.ctc2(V0, 27);
    c.vu0().vnop();
    c.vu0().vnop();
    c.vcallmsr();
    c.cfc2(4, 1);
    c.cfc2(3, 2);
    let far = c.g[V1][0] != 0;
    c.g[V0][0] = 2;
    if far {
        c.cycles += 2;
        c.g[V0][0] = 1;
        abi::ret(c);
        return;
    }
    c.cycles += 2;
    if c.g[A0][0] == 0 {
        c.g[V0][0] = 0;
    }
    abi::ret(c);
}

/// `PS2GraphicsMan_v97` (0x00380380): project an object's four corner
/// texcoords/colours into `pos` (3 floats each), `uv` (2 floats each) and
/// `col` (4 floats each), scaling the model's corner table by its scale.
///
/// `obj` (+0x80 model, +0x98 extra offset), `idx` (corner base), `pos`,
/// `uv`, `col` are passed in `a1`, `a2`, `a3`, `t0`, `t1` as the original
/// reads them.
pub fn ps2_graphics_man_v97(c: &mut Cpu) {
    c.cycles += 42;
    let obj = abi::arg(c, 1);
    let pos = abi::arg(c, 3);
    let col = abi::arg64(c, 5);
    c.g[T2][0] = c.lw(p(obj, 0x80)); // model
    c.g[A2][0] = sx((abi::arg(c, 2) as u32) << 4);
    c.g[T3][0] = col;
    c.g[SP][0] = sx(r(c, SP).wrapping_sub(0x20));
    c.g[V0][0] = c.lw(p(r(c, T2), 8)); // corner table offset
    c.g[T4][0] = 3;
    c.g[T1][0] = c.lw(p(obj, 0x98)); // extra offset
    c.g[A2][0] = add32(c.g[A2][0], c.g[V0][0]);
    c.g[A1][0] = c.lw(p(r(c, T2), 0x24)); // vertex base offset
    c.g[V0][0] = c.lw(p(r(c, A2), 4));
    c.lwc1(3, gp_4(c, -0x2760)); // 3.0517578e-5
    c.g[A0][0] = c.lw(p(r(c, V0), 0x20));
    c.g[AT][0] = 0x3980_0000;
    c.mtc1(1, 5); // f5 = 1/4096
    c.g[V1][0] = c.lw(r(c, A0));
    c.lwc1(4, gp_4(c, -0x275c)); // 0.032258
    c.g[V0][0] = c.lw(p(r(c, V1), 4));
    c.g[T1][0] = add32(c.g[V0][0], c.g[T1][0]); // data
    c.g[V0][0] = add32(c.g[V0][0], c.g[A1][0]);
    c.g[V1][0] = c.lw(p(r(c, T1), 0x14)); // colour record
    c.g[A0][0] = c.lw(p(r(c, V0), 4)); // vertex source
    c.ldl(2, p(r(c, T2), 0x1f));
    c.ldr(2, p(r(c, T2), 0x18)); // scale x, y
    c.g[A1][0] = c.lw(p(r(c, T2), 0x20)); // scale z
    c.sdl(2, p(r(c, SP), 0x17));
    c.sdr(2, p(r(c, SP), 0x10));
    c.sw(p(r(c, SP), 0x18), c.g[A1][0]);
    c.g[V1][0] = sx((c.g[V1][0] as u32).wrapping_add(0x10));
    let vbase = r(c, A0);
    c.g[A1][0] = sx(vbase.wrapping_add(0xa0)); // uv source
    c.lwc1(0, p(r(c, SP), 0x10));
    c.g[A0][0] = sx(vbase.wrapping_add(0x80)); // texcoord source
    c.lwc1(1, p(r(c, SP), 0x14));
    c.lwc1(2, p(r(c, SP), 0x18));
    c.mul_s(0, 0, 3);
    c.mul_s(1, 1, 3);
    c.mul_s(2, 2, 3);
    c.swc1(0, r(c, SP)); // k.x
    c.mov_s(6, 0);
    c.mov_s(3, 1); // k.y
    c.swc1(1, p(r(c, SP), 4));
    c.swc1(2, p(r(c, SP), 8));
    c.mov_s(1, 2); // k.z
    let mut pos = pos;
    loop {
        c.cycles += 58;
        // Position: the corner shorts scaled into world units.
        c.g[V0][0] = c.lh(r(c, A1));
        c.g[T4][0] = sx((c.g[T4][0] as u32).wrapping_sub(1));
        c.mtc1(2, 0);
        c.cvt_s_w(0, 0);
        c.mul_s(0, 0, 6);
        c.swc1(0, pos);
        c.g[V0][0] = c.lh(p(r(c, A1), 2));
        c.mtc1(2, 0);
        c.cvt_s_w(0, 0);
        c.mul_s(0, 0, 3);
        c.swc1(0, p(pos, 4));
        c.g[V0][0] = c.lh(p(r(c, A1), 4));
        c.g[A1][0] = sx((c.g[A1][0] as u32).wrapping_add(6));
        c.mtc1(2, 0);
        c.cvt_s_w(0, 0);
        c.mul_s(0, 0, 1);
        c.swc1(0, p(pos, 8));
        pos = pos.wrapping_add(0xc);
        c.g[A3][0] = sx(pos);
        // UV: the texcoord shorts scaled to 0..1.
        c.g[V0][0] = c.lh(r(c, A0));
        c.mtc1(2, 0);
        c.cvt_s_w(0, 0);
        c.mul_s(0, 0, 5);
        c.swc1(0, r(c, T0));
        c.g[V0][0] = c.lh(p(r(c, A0), 2));
        c.g[A0][0] = sx((c.g[A0][0] as u32).wrapping_add(4));
        c.mtc1(2, 0);
        c.cvt_s_w(0, 0);
        c.mul_s(0, 0, 5);
        c.swc1(0, p(r(c, T0), 4));
        c.g[T0][0] = sx((c.g[T0][0] as u32).wrapping_add(8));
        // Colour: the pack16 record's four channels unpacked.
        c.g[V0][0] = c.lhu(r(c, V1));
        c.g[V0][0] &= 0x1f;
        c.mtc1(2, 0);
        c.cvt_s_w(0, 0);
        c.mul_s(0, 0, 4);
        c.swc1(0, p(r(c, T3), 4));
        c.g[V0][0] = c.lhu(r(c, V1));
        c.g[V0][0] = sx((c.g[V0][0] as u32) >> 5);
        c.g[V0][0] &= 0x1f;
        c.mtc1(2, 0);
        c.cvt_s_w(0, 0);
        c.mul_s(0, 0, 4);
        c.swc1(0, p(r(c, T3), 8));
        c.g[V0][0] = c.lhu(r(c, V1));
        c.g[V0][0] = sx((c.g[V0][0] as u32) >> 10);
        c.g[V0][0] &= 0x1f;
        c.mtc1(2, 0);
        c.cvt_s_w(0, 0);
        c.mul_s(0, 0, 4);
        c.swc1(0, p(r(c, T3), 0xc));
        c.g[V0][0] = c.lhu(r(c, V1));
        c.g[V1][0] = sx((c.g[V1][0] as u32).wrapping_add(2));
        c.g[V0][0] = sx((c.g[V0][0] as u32) >> 15);
        c.mtc1(2, 0);
        c.cvt_s_w(0, 0);
        c.swc1(0, r(c, T3));
        let more = (c.g[T4][0] as i64) >= 0;
        c.g[T3][0] = sx((c.g[T3][0] as u32).wrapping_add(0x10));
        if !more {
            c.cycles += 2;
            c.g[SP][0] = sx((c.g[SP][0] as u32).wrapping_add(0x20));
            abi::ret(c);
            return;
        }
        if event_due(c) {
            deliver_event_here(c, 0x0038_0428);
        }
    }
}

/// `PS2GraphicsMan_AddView` (0x00386688): copy view `idx`'s two matrices
/// from `+0x6af0` into the array at `+0x5930`, copy its pair word, and bump
/// the count.
pub fn ps2_graphics_man_add_view(c: &mut Cpu) {
    c.cycles += 21;
    let gm = abi::arg(c, 0);
    let idx = abi::arg(c, 1);
    c.g[V0][0] = sx((idx as u32) << 6);
    c.g[A2][0] = sx(gm.wrapping_add(GM_VIEW_MATRICES));
    c.g[V0][0] = sx((c.g[V0][0] as u32).wrapping_add(gm));
    c.g[V0][0] = sx((c.g[V0][0] as u32).wrapping_add(GM_VIEW_ENTRIES));
    let src = r(c, A2);
    let dst = r(c, V0);
    c.lqc2(1, src);
    c.lqc2(2, p(src, 0x10));
    c.lqc2(3, p(src, 0x20));
    c.lqc2(4, p(src, 0x30));
    c.sqc2(1, dst);
    c.sqc2(2, p(dst, 0x10));
    c.sqc2(3, p(dst, 0x20));
    c.sqc2(4, p(dst, 0x30));
    c.g[V1][0] = sx((idx as u32) << 3);
    c.g[V1][0] = sx((c.g[V1][0] as u32).wrapping_add(gm));
    c.g[A1][0] = sx((idx as u32).wrapping_add(1));
    c.ldl(2, p(gm, GM_VIEW_PAIR_SRC + 7));
    c.ldr(2, p(gm, GM_VIEW_PAIR_SRC));
    c.sdl(2, p(r(c, V1), GM_VIEW_PAIRS + 7));
    c.sdr(2, p(r(c, V1), GM_VIEW_PAIRS));
    c.sw(p(gm, GM_VIEW_COUNT), c.g[A1][0]);
    abi::ret(c);
}

/// `void PS2GraphicsMan_v60(void* self, VEntry* item)` (0x37cc30): unlock the
/// texture's VRAM and notify the texture manager.
pub fn ps2_graphics_man_v60(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 10;
        let frame = Frame::open(c, 0x40);
        frame.save(c, S0, 0x30);
        frame.save(c, S1, 0x20);
        frame.save(c, S2, 0x10);
        c.g[S1][0] = c.g[A1][0];
        frame.save_ra(c, 0);
        c.g[S2][0] = 0xffff_ffff_ffff_ffff;
        c.g[S0][0] = c.g[A0][0];
        c.g[A1][0] = Addr(p(c.g[S1][0] as u32, 4)).lw(c);
        if c.g[A1][0] != c.g[S2][0] {
            c.cycles += 9;
            c.g[A0][0] = Addr(p(c.g[S0][0] as u32, 0x18f4)).lw(c);
            call_ptr(c, 0x0036_7b60, 0x0037_cc60)?;
            c.g[V0][0] = Addr(p(c.g[S0][0] as u32, 0x10d8)).lw(c);
            c.g[A1][0] = Addr(p(c.g[S1][0] as u32, 4)).lw(c);
            c.g[A0][0] = Addr(p(c.g[V0][0] as u32, 0x190)).lh(c);
            c.g[V1][0] = Addr(p(c.g[V0][0] as u32, 0x194)).lw(c);
            let target = c.g[V1][0] as u32;
            c.g[A0][0] = sx(p(c.g[S0][0] as u32, c.g[A0][0] as u32));
            call_ptr(c, target, 0x0037_cc78)?;
            Addr(p(c.g[S1][0] as u32, 4)).sw(c, c.g[S2][0]);
        }
        frame.restore(c, S0, 0x30);
        frame.restore(c, S1, 0x20);
        frame.restore(c, S2, 0x10);
        c.cycles += 6;
        frame.restore_ra(c, 0);
        frame.close(c);
        Ok(())
    })
}

/// `void RailTube_dtor(RailTube* self, int flags)` (0x372660).
pub fn rail_tube_dtor(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 11;
        let frame = Frame::open(c, 0x30);
        c.g[V0][0] = 0x0049_0000;
        frame.save(c, S0, 0x20);
        c.g[V0][0] = sx((c.g[V0][0] as u32).wrapping_add(0x3068));
        frame.save(c, S1, 0x10);
        c.g[S0][0] = c.g[A0][0];
        frame.save_ra(c, 0);
        Addr(c.g[S0][0] as u32).sw(c, c.g[V0][0]);
        c.g[A0][0] = Addr(p(c.g[S0][0] as u32, 8)).lw(c);
        let no_buf = c.g[A0][0] == 0;
        c.g[S1][0] = c.g[A1][0];
        if !no_buf {
            c.cycles += 2;
            call_ptr(c, 0x0031_7e98, 0x0037_2694)?;
        }
        c.cycles += 5;
        c.g[V0][0] = 0x0049_0000;
        c.g[V1][0] = c.g[S1][0] & 1;
        c.g[V0][0] = sx((c.g[V0][0] as u32).wrapping_sub(0x7980));
        let keep = c.g[V1][0] == 0;
        Addr(c.g[S0][0] as u32).sw(c, c.g[V0][0]);
        if !keep {
            c.cycles += 2;
            c.g[A0][0] = c.g[S0][0];
            call_ptr(c, 0x0031_7e50, 0x0037_26b0)?;
        }
        frame.restore(c, S0, 0x20);
        frame.restore(c, S1, 0x10);
        c.cycles += 5;
        frame.restore_ra(c, 0);
        frame.close(c);
        Ok(())
    })
}

/// `DynamicEmitter_Load(emitter, data)` 0x371318: let the data object's
/// loader fill a local parameter block, then copy the position, range and
/// count fields into the emitter.
pub fn dynamic_emitter_load(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 26;
        let frame = Frame::open(c, 0x40);
        let data64 = abi::arg64(c, 1);
        let data = data64 as u32;
        c.g[A3][0] = data64;
        frame.save(c, S0, 0x30);
        c.g[A1][0] = sp(c) as u64;
        c.g[A2][0] = 0x14;
        frame.save_ra(c, 0x20);
        let this = abi::arg(c, 0);
        c.g[S0][0] = sx(this);
        let src = lw_at(c, data, 0) as u32;
        c.g[V1][0] = src as u64;
        c.g[A0][0] = Addr(p(src, 0x10)).lh(c);
        c.g[V0][0] = lw_at(c, src, 0x14);
        let func = r32(c, V0);
        c.g[A0][0] = sx(data.wrapping_add(r32(c, A0)));
        call_ptr(c, func, 0x0037_1348)?;
        let base = sp(c);
        c.lwc1(0, base);
        c.lwc1(1, p(base, 4));
        c.g[V1][0] = lw_at(c, base, 0xc);
        c.g[A0][0] = lw_at(c, base, 8);
        c.g[V0][0] = lw_at(c, base, 0x10);
        c.swc1(0, this);
        Addr(p(this, 0x17c)).sw(c, c.g[V0][0]);
        c.swc1(1, p(this, 0x28));
        Addr(p(this, 0x170)).sw(c, c.g[V1][0]);
        Addr(p(this, 0x174)).sw(c, c.g[A0][0]);
        frame.restore(c, S0, 0x30);
        frame.restore_ra(c, 0x20);
        frame.close(c);
        Ok(())
    })
}

/// One of the three identical `vu0` matrix products: load the two matrices
/// from `a` and `b` into VF4..VF11, multiply rows into VF12..VF15 and store
/// them at `out`. The COP2 operations are issued in the original's order so
/// VF/ACC and the VU0 flags end exactly as they do there.
pub(crate) fn transform_matrix(c: &mut Cpu, a: u32, b: u32, out: u32) {
    c.lqc2(4, a);
    c.lqc2(5, p(a, 0x10));
    c.lqc2(6, p(a, 0x20));
    c.lqc2(7, p(a, 0x30));
    c.lqc2(8, b);
    c.lqc2(9, p(b, 0x10));
    c.lqc2(10, p(b, 0x20));
    c.lqc2(11, p(b, 0x30));
    c.vu0().mula(0b1111, 4, Src::Bc(8, X));
    c.vu0().madda(0b1111, 5, Src::Bc(8, Y));
    c.vu0().madda(0b1111, 6, Src::Bc(8, Z));
    c.vu0().madd(0b1111, 12, 7, Src::Bc(8, W));
    c.vu0().mula(0b1111, 4, Src::Bc(9, X));
    c.vu0().madda(0b1111, 5, Src::Bc(9, Y));
    c.vu0().madda(0b1111, 6, Src::Bc(9, Z));
    c.vu0().madd(0b1111, 13, 7, Src::Bc(9, W));
    c.vu0().mula(0b1111, 4, Src::Bc(10, X));
    c.vu0().madda(0b1111, 5, Src::Bc(10, Y));
    c.vu0().madda(0b1111, 6, Src::Bc(10, Z));
    c.vu0().madd(0b1111, 14, 7, Src::Bc(10, W));
    c.vu0().mula(0b1111, 4, Src::Bc(11, X));
    c.vu0().madda(0b1111, 5, Src::Bc(11, Y));
    c.vu0().madda(0b1111, 6, Src::Bc(11, Z));
    c.vu0().madd(0b1111, 15, 7, Src::Bc(11, W));
    c.sqc2(12, out);
    c.sqc2(13, p(out, 0x10));
    c.sqc2(14, p(out, 0x20));
    c.sqc2(15, p(out, 0x30));
}

/// A 4x4 matrix moved through the quad registers (the original does
/// `lqc2`/`sqc2` twice instead of a plain `lq`/`sq` to keep the quad pipeline).
pub(crate) fn copy_matrix(c: &mut Cpu, from: u32, to: u32) {
    c.lqc2(1, from);
    c.lqc2(2, p(from, 0x10));
    c.lqc2(3, p(from, 0x20));
    c.lqc2(4, p(from, 0x30));
    c.sqc2(1, to);
    c.sqc2(2, p(to, 0x10));
    c.sqc2(3, p(to, 0x20));
    c.sqc2(4, p(to, 0x30));
}

/// `void BoaderShadow_ComputeProjection(void* obj, Vec3* a, Vec3* b,
/// Vec3* dir, Mat4* bones, int f)` (0x374d00).
///
/// `a0`/`t1` is the shadow object, `a1` a reference direction, `a2` the
/// position vector, `a3` the shadow direction, `t0` the bone matrix table.
/// The int argument is unused (the original immediately reuses `t1` for the
/// object pointer; the fixed count of six bone entries is hard-coded).
pub fn boader_shadow_compute_projection(c: &mut Cpu) {
    ssx3_ee_rt::prof::enter(c, 0x0037_4d00);

    // ---------------------------------------------------------------
    // Prologue and normalisation of the `b` vector (`a2`) into the frame
    // scratch vector at `sp+0`.
    // ---------------------------------------------------------------
    c.cycles += 30;
    let sp = (c.g[SP][0] as u32).wrapping_sub(0x190);
    c.g[SP][0] = sx(sp);
    c.mtc1(0, 3); // f3 = 0.0
    c.sq(16, p(sp, 0x120));
    c.g[T1][0] = c.g[A0][0];
    c.sq(17, p(sp, 0x110));
    c.swc1(31, p(sp, 0x188));
    c.swc1(30, p(sp, 0x180));
    c.swc1(29, p(sp, 0x178));
    c.swc1(28, p(sp, 0x170));
    c.swc1(27, p(sp, 0x168));
    c.swc1(26, p(sp, 0x160));
    c.swc1(25, p(sp, 0x158));
    c.swc1(24, p(sp, 0x150));
    c.swc1(23, p(sp, 0x148));
    c.swc1(22, p(sp, 0x140));
    c.swc1(21, p(sp, 0x138));
    c.swc1(20, p(sp, 0x130));
    let obj = c.g[T1][0] as u32;

    c.lwc1(4, c.g[A2][0] as u32);
    c.lwc1(5, p(c.g[A2][0] as u32, 0x4));
    c.mul_s(0, 4, 4);
    c.lwc1(6, p(c.g[A2][0] as u32, 0x8));
    c.mul_s(1, 5, 5);
    c.mul_s(2, 6, 6);
    c.add_s(0, 0, 1);
    c.add_s(0, 0, 2);
    c.sqrt_s(1, 0);
    c.c_eq_s(1, 3);
    if c.fcc() {
        // Zero length: keep the raw x component, leave y/z from `a2`.
        c.swc1(4, sp);
        c.cycles += 2;
        c.swc1(5, p(sp, 0x4));
        c.swc1(6, p(sp, 0x8));
    } else {
        c.cycles += 10;
        c.g[AT][0] = 0x3f80_0000;
        c.mtc1(1, 0);
        c.div_s(0, 0, 1);
        c.mul_s(1, 6, 0);
        c.mul_s(2, 4, 0);
        c.mul_s(0, 5, 0);
        c.swc1(1, p(sp, 0x8));
        c.swc1(2, sp);
        c.swc1(0, p(sp, 0x4));
    }

    // ---------------------------------------------------------------
    // Copy that vector to `obj+0`, then normalise the direction `a3` into
    // the frame and set `v0 = obj+0x18` for the next pass.
    // ---------------------------------------------------------------
    c.cycles += 21;
    c.ldl(2, p(sp, 0x7));
    c.ldr(2, sp);
    c.g[V1][0] = c.lw(p(sp, 0x8));
    c.sdl(2, p(obj, 0x7));
    c.sdr(2, obj);
    c.sw(p(obj, 0x8), c.g[V1][0]);
    c.mtc1(0, 3);
    c.g[V0][0] = sx(p(obj, 0x18));
    c.lwc1(4, c.g[A3][0] as u32);
    c.lwc1(5, p(c.g[A3][0] as u32, 0x4));
    c.mul_s(0, 4, 4);
    c.lwc1(6, p(c.g[A3][0] as u32, 0x8));
    c.mul_s(1, 5, 5);
    c.mul_s(2, 6, 6);
    c.add_s(0, 0, 1);
    c.add_s(0, 0, 2);
    c.sqrt_s(1, 0);
    c.c_eq_s(1, 3);
    if c.fcc() {
        c.swc1(4, sp);
        c.cycles += 2;
        c.swc1(5, p(sp, 0x4));
        c.swc1(6, p(sp, 0x8));
    } else {
        c.cycles += 10;
        c.g[AT][0] = 0x3f80_0000;
        c.mtc1(1, 0);
        c.div_s(0, 0, 1);
        c.mul_s(1, 6, 0);
        c.mul_s(2, 4, 0);
        c.mul_s(0, 5, 0);
        c.swc1(1, p(sp, 0x8));
        c.swc1(2, sp);
        c.swc1(0, p(sp, 0x4));
    }

    // ---------------------------------------------------------------
    // Direction to `obj+0x18`, reference vector `a1` to `obj+0x0c` and to
    // the scratch vector (negated), and the dot product into `obj+0x24`.
    // `v0` becomes 1 when `b` is exactly parallel to `dir`.
    // ---------------------------------------------------------------
    c.cycles += 44;
    let dir = p(obj, shadow::DIR);
    c.ldl(7, p(sp, 0x7));
    c.ldr(7, sp);
    c.g[T3][0] = c.lw(p(sp, 0x8));
    c.sdl(7, p(dir, 0x7));
    c.sdr(7, dir);
    c.sw(p(dir, 0x8), c.g[T3][0]);
    c.mtc1(0, 2); // f2 = 0.0
    c.g[V0][0] = 0;
    c.lwc1(3, p(c.g[A1][0] as u32, 0x8));
    c.lwc1(0, c.g[A1][0] as u32);
    c.lwc1(1, p(c.g[A1][0] as u32, 0x4));
    c.swc1(3, p(sp, 0x8));
    c.swc1(0, sp);
    c.swc1(1, p(sp, 0x4));
    c.swc1(2, p(sp, 0x18));
    c.swc1(2, p(sp, 0x10));
    c.swc1(2, p(sp, 0x14));
    c.ldl(5, p(sp, 0x7));
    c.ldr(5, sp);
    c.g[A2][0] = c.lw(p(sp, 0x8));
    c.sdl(5, p(obj, 0x13));
    c.sdr(5, p(obj, 0x0c));
    c.sw(p(obj, 0x14), c.g[A2][0]);
    let vec_a = p(obj, shadow::VEC_A);
    c.lwc1(7, p(dir, 0x0));
    c.lwc1(8, p(dir, 0x4));
    c.neg_s(3, 7);
    c.lwc1(9, p(dir, 0x8));
    c.neg_s(5, 8);
    c.lwc1(0, p(vec_a, 0x0));
    c.lwc1(1, p(vec_a, 0x4));
    c.neg_s(6, 9);
    c.mul_s(0, 3, 0);
    c.lwc1(2, p(vec_a, 0x8));
    c.mul_s(1, 5, 1);
    c.lwc1(4, p(obj, shadow::VEC_B));
    c.mul_s(2, 6, 2);
    c.swc1(3, sp);
    c.c_eq_s(4, 7);
    c.swc1(5, p(sp, 0x4));
    c.add_s(0, 0, 1);
    c.swc1(6, p(sp, 0x8));
    c.add_s(0, 0, 2);
    let different = !c.fcc();
    c.swc1(0, p(obj, shadow::DOT));
    if !different {
        // b.x == dir.x: try the remaining components.
        c.cycles += 4;
        c.lwc1(0, p(obj, shadow::VEC_B + 0x4));
        c.c_eq_s(0, 8);
        if c.fcc() {
            c.cycles += 5;
            c.lwc1(0, p(obj, shadow::VEC_B + 0x8));
            c.c_eq_s(0, 9);
            if c.fcc() {
                c.g[V0][0] = 0x1;
            }
        }
    }

    // ---------------------------------------------------------------
    // If `b` is not parallel to `dir`, check it against the negated `dir`;
    // when `b` is parallel to neither axis, bias `obj+0` by a global. `f5`
    // carries `obj+0x1c` into the first cross product below.
    // ---------------------------------------------------------------
    c.cycles += 2;
    let mut bias_b = false;
    if c.g[V0][0] != 0 {
        c.lwc1(0, p(obj, shadow::VEC_B));
        bias_b = true;
    } else {
        c.cycles += 13;
        c.lwc1(0, p(dir, 0x0));
        c.g[V0][0] = 0;
        c.lwc1(2, p(dir, 0x4));
        c.lwc1(3, p(dir, 0x8));
        c.neg_s(0, 0);
        c.lwc1(1, p(obj, shadow::VEC_B));
        c.neg_s(2, 2);
        c.neg_s(3, 3);
        c.c_eq_s(1, 0);
        c.swc1(0, sp);
        c.swc1(2, p(sp, 0x4));
        let different = !c.fcc();
        c.swc1(3, p(sp, 0x8));
        if !different {
            c.cycles += 4;
            c.lwc1(0, p(obj, shadow::VEC_B + 0x4));
            c.c_eq_s(0, 2);
            if c.fcc() {
                c.cycles += 5;
                c.lwc1(0, p(obj, shadow::VEC_B + 0x8));
                c.c_eq_s(0, 3);
                if c.fcc() {
                    c.g[V0][0] = 0x1;
                }
            }
        }
        c.cycles += 2;
        if c.g[V0][0] == 0 {
            c.lwc1(5, p(dir, 0x4));
        } else {
            c.cycles += 1;
            c.lwc1(0, p(obj, shadow::VEC_B));
            bias_b = true;
        }
    }
    if bias_b {
        c.cycles += 4;
        c.lwc1(1, p(c.g[GP][0] as u32, 0xffff_d808)); // gp - 0x27f8
        c.add_s(0, 0, 1);
        c.swc1(0, p(obj, shadow::VEC_B));
        c.lwc1(5, p(dir, 0x4));
    }

    // ---------------------------------------------------------------
    // First cross product (`dir` x `b`), normalised into the frame vector
    // at `sp+0`; `v0 = obj+0x34` receives it in the next block.
    // ---------------------------------------------------------------
    c.cycles += 29;
    c.g[V0][0] = sx(p(obj, shadow::MAT_C));
    c.lwc1(4, p(obj, 0x4));
    c.lwc1(1, p(obj, 0x20));
    c.lwc1(0, p(obj, 0x8));
    c.lwc1(6, p(dir, 0x0));
    c.mul_s(7, 4, 1);
    c.lwc1(2, p(obj, 0x0));
    c.mul_s(3, 0, 5);
    c.mul_s(0, 0, 6);
    c.mul_s(1, 2, 1);
    c.sub_s(7, 7, 3);
    c.mul_s(2, 2, 5);
    c.sub_s(8, 0, 1);
    c.mul_s(4, 4, 6);
    c.swc1(7, p(sp, 0x20));
    c.mul_s(0, 7, 7);
    c.mul_s(3, 8, 8);
    c.swc1(8, p(sp, 0x24));
    c.sub_s(2, 2, 4);
    c.mtc1(0, 5); // f5 = 0.0
    c.add_s(0, 0, 3);
    c.mul_s(1, 2, 2);
    c.swc1(2, p(sp, 0x28));
    c.add_s(0, 0, 1);
    c.sqrt_s(1, 0);
    c.c_eq_s(1, 5);
    if c.fcc() {
        c.swc1(7, sp);
        c.cycles += 2;
        c.swc1(8, p(sp, 0x4));
        c.swc1(2, p(sp, 0x8));
    } else {
        c.cycles += 10;
        c.g[AT][0] = 0x3f80_0000;
        c.mtc1(1, 0);
        c.div_s(0, 0, 1);
        c.mul_s(1, 2, 0);
        c.mul_s(2, 7, 0);
        c.mul_s(0, 8, 0);
        c.swc1(1, p(sp, 0x8));
        c.swc1(2, sp);
        c.swc1(0, p(sp, 0x4));
    }

    // ---------------------------------------------------------------
    // `obj+0x34` gets that vector; a second cross product (`dir` x the
    // `obj+0x1c..` plane row) lands in the frame at `sp+0x10..0x18` and is
    // normalised into `sp+0`, then written to `obj+0x28` below.
    // ---------------------------------------------------------------
    c.cycles += 36;
    let mat_c = p(obj, shadow::MAT_C);
    c.ldl(3, p(sp, 0x7));
    c.ldr(3, sp);
    c.g[A0][0] = c.lw(p(sp, 0x8));
    c.sdl(3, p(mat_c, 0x7));
    c.sdr(3, mat_c);
    c.sw(p(mat_c, 0x8), c.g[A0][0]);
    c.mtc1(0, 8); // f8 = 0.0
    c.g[V0][0] = sx(p(obj, shadow::MAT_B));
    c.lwc1(5, p(obj, 0x38));
    c.lwc1(4, p(obj, 0x1c));
    c.lwc1(1, p(obj, 0x3c));
    c.lwc1(0, p(obj, 0x20));
    c.lwc1(6, p(obj, 0x34));
    c.mul_s(7, 4, 1);
    c.lwc1(2, p(dir, 0x0));
    c.mul_s(3, 0, 5);
    c.mul_s(0, 0, 6);
    c.mul_s(1, 2, 1);
    c.mul_s(2, 2, 5);
    c.sub_s(7, 7, 3);
    c.sub_s(5, 0, 1);
    c.mul_s(4, 4, 6);
    c.mul_s(0, 7, 7);
    c.swc1(7, p(sp, 0x10));
    c.mul_s(3, 5, 5);
    c.swc1(5, p(sp, 0x14));
    c.sub_s(2, 2, 4);
    c.add_s(0, 0, 3);
    c.mul_s(1, 2, 2);
    c.swc1(2, p(sp, 0x18));
    c.add_s(0, 0, 1);
    c.sqrt_s(1, 0);
    c.c_eq_s(1, 8);
    if c.fcc() {
        c.swc1(7, sp);
        c.cycles += 2;
        c.swc1(5, p(sp, 0x4));
        c.swc1(2, p(sp, 0x8));
    } else {
        c.cycles += 10;
        c.g[AT][0] = 0x3f80_0000;
        c.mtc1(1, 0);
        c.div_s(0, 0, 1);
        c.mul_s(1, 2, 0);
        c.mul_s(2, 7, 0);
        c.mul_s(0, 5, 0);
        c.swc1(1, p(sp, 0x8));
        c.swc1(2, sp);
        c.swc1(0, p(sp, 0x4));
    }

    // ---------------------------------------------------------------
    // `obj+0x28` gets the last vector. Set up the basis (rows built from the
    // two cross products and the direction), the light matrix and the six
    // bone gathers.
    // ---------------------------------------------------------------
    c.cycles += 100;
    let mat_b = p(obj, shadow::MAT_B);
    c.ldl(7, p(sp, 0x7));
    c.ldr(7, sp);
    c.g[T3][0] = c.lw(p(sp, 0x8));
    c.sdl(7, p(mat_b, 0x7));
    c.sdr(7, mat_b);
    c.g[T5][0] = sx(p(sp, 0x50));
    c.sw(p(mat_b, 0x8), c.g[T3][0]);
    c.g[T4][0] = sx(p(obj, shadow::LIGHT));
    c.g[AT][0] = 0x3f80_0000;
    c.mtc1(1, 18); // f18 = 1.0
    c.g[V1][0] = 0x004a_0000;
    c.lwc1(17, p(obj, shadow::VEC_A));
    c.g[A0][0] = 0x004a_0000;
    c.lwc1(15, p(obj, 0x10));
    c.mov_s(31, 18);
    c.lwc1(5, p(obj, 0x34));
    c.g[T3][0] = sx(p(sp, 0xd0));
    c.lwc1(7, p(obj, 0x38));
    c.g[T6][0] = sx(p(sp, 0x90));
    c.lwc1(8, p(obj, 0x28));
    c.mul_s(3, 17, 5);
    c.lwc1(9, p(obj, 0x2c));
    c.mul_s(12, 15, 7);
    c.mul_s(2, 17, 8);
    c.lwc1(13, p(obj, 0x14));
    c.mul_s(14, 15, 9);
    c.lwc1(0, p(obj, 0x3c));
    c.lwc1(1, p(obj, 0x30));
    c.add_s(3, 3, 12);
    c.swc1(5, p(obj, 0x50));
    c.mov_s(28, 5);
    c.lwc1(10, p(dir, 0x0));
    c.mul_s(12, 13, 1);
    c.lwc1(11, p(dir, 0x4));
    c.mul_s(5, 13, 0);
    c.add_s(2, 2, 14);
    c.lwc1(4, p(obj, 0x20));
    c.mul_s(16, 15, 11);
    c.swc1(0, p(obj, 0x58));
    c.mul_s(6, 17, 10);
    c.mov_s(22, 0);
    c.add_s(2, 2, 12);
    c.swc1(1, p(obj, 0x68));
    c.add_s(3, 3, 5);
    c.swc1(10, p(obj, 0x70));
    c.swc1(11, p(obj, 0x74));
    c.mul_s(0, 13, 4);
    c.swc1(7, p(obj, 0x54));
    c.add_s(6, 6, 16);
    c.swc1(8, p(obj, 0x60));
    c.mov_s(21, 1);
    c.swc1(9, p(obj, 0x64));
    c.mov_s(24, 10);
    c.swc1(2, p(sp, 0x14));
    c.add_s(6, 6, 0);
    c.swc1(3, p(sp, 0x10));
    c.mov_s(23, 11);
    c.swc1(18, p(obj, 0x8c));
    c.mov_s(27, 7);
    c.swc1(4, p(obj, 0x78));
    c.mov_s(26, 8);
    c.sw(p(obj, 0x80), 0u64);
    c.mov_s(25, 9);
    c.sw(p(obj, 0x84), 0u64);
    c.mov_s(20, 4);
    c.sw(p(obj, 0x88), 0u64);
    c.g[A2][0] = sx(p(obj, shadow::PROJECTION));
    c.swc1(17, p(sp, 0x30));
    c.g[T8][0] = sx(p(obj, shadow::VIEW));
    c.swc1(15, p(sp, 0x34));
    c.g[T2][0] = sx(p(obj, shadow::BONES));
    c.swc1(13, p(sp, 0x38));
    c.g[A1][0] = sx(p(obj, shadow::BONE_INDEX));
    c.swc1(18, p(sp, 0x3c));
    c.g[A3][0] = 0x5;
    c.swc1(6, p(sp, 0x18));
    c.lwc1(16, p(obj, 0x88));
    c.swc1(18, p(sp, 0x1c));
    c.lwc1(11, p(c.g[V1][0] as u32, 0x431c));
    c.mov_s(30, 16);
    c.lq(2, p(sp, 0x10));
    c.mov_s(29, 16);
    c.lwc1(10, p(c.g[A0][0] as u32, 0x4320));
    c.mov_s(14, 11);
    c.sq(2, sp);
    c.mov_s(12, 11);
    c.mov_s(13, 10);
    c.mov_s(15, 10);
    c.lwc1(0, p(sp, 0x0));
    c.lwc1(1, p(sp, 0x4));
    c.lwc1(2, p(sp, 0x8));
    c.neg_s(0, 0);
    c.neg_s(1, 1);
    c.neg_s(2, 2);
    c.swc1(0, p(obj, 0x5c));
    c.mov_s(19, 0);
    c.swc1(1, p(obj, 0x6c));
    c.mov_s(18, 1);
    c.swc1(2, p(obj, 0x7c));
    c.mov_s(17, 2);

    // Six bone entries: index from `obj+0x17c..`, entry stride 0x40, row
    // taken from `+0x30` and transformed by the current basis.
    'gather: loop {
        c.cycles += 48;
        c.g[V1][0] = c.lw(c.g[A1][0] as u32);
        c.g[V1][0] = sx((c.g[V1][0] as u32) << 6);
        c.g[V1][0] = sx((c.g[V1][0] as u32).wrapping_add(c.g[T0][0] as u32));
        c.lq(2, p(c.g[V1][0] as u32, 0x30));
        c.sq(2, p(sp, 0x40));
        c.lwc1(1, p(sp, 0x40));
        c.lwc1(0, p(sp, 0x44));
        c.mul_s(6, 1, 30);
        c.lwc1(5, p(sp, 0x48));
        c.mul_s(8, 0, 27);
        c.lwc1(7, p(sp, 0x4c));
        c.mul_s(2, 0, 25);
        c.mul_s(9, 0, 16);
        c.mul_s(4, 1, 28);
        c.mul_s(3, 1, 26);
        c.mul_s(0, 0, 23);
        c.mul_s(1, 1, 24);
        c.add_s(4, 4, 8);
        c.add_s(3, 3, 2);
        c.add_s(1, 1, 0);
        c.mul_s(0, 5, 22);
        c.mul_s(2, 5, 21);
        c.mul_s(8, 5, 29);
        c.mul_s(5, 5, 20);
        c.add_s(6, 6, 9);
        c.add_s(4, 4, 0);
        c.add_s(3, 3, 2);
        c.add_s(1, 1, 5);
        c.mul_s(0, 7, 19);
        c.mul_s(5, 7, 31);
        c.mul_s(2, 7, 18);
        c.add_s(6, 6, 8);
        c.mul_s(7, 7, 17);
        c.add_s(4, 4, 0);
        c.add_s(3, 3, 2);
        c.add_s(1, 1, 7);
        c.add_s(6, 6, 5);
        c.swc1(4, p(sp, 0x20));
        c.swc1(3, p(sp, 0x24));
        c.swc1(1, p(sp, 0x28));
        c.swc1(6, p(sp, 0x2c));
        c.lq(2, p(sp, 0x20));
        c.sq(2, p(sp, 0x10));
        c.lwc1(0, p(sp, 0x10));
        c.c_lt_s(0, 14);
        if c.fcc() {
            c.mov_s(14, 0);
        }
        c.cycles += 4;
        c.c_lt_s(13, 0);
        if c.fcc() {
            c.mov_s(13, 0);
        }
        c.cycles += 5;
        c.lwc1(0, p(sp, 0x14));
        c.c_lt_s(0, 11);
        if c.fcc() {
            c.mov_s(11, 0);
        }
        c.cycles += 4;
        c.c_lt_s(10, 0);
        if c.fcc() {
            c.mov_s(10, 0);
        }
        c.cycles += 5;
        c.lwc1(0, p(sp, 0x18));
        c.c_lt_s(0, 12);
        if c.fcc() {
            c.mov_s(12, 0);
        }
        c.cycles += 4;
        c.c_lt_s(15, 0);
        if c.fcc() {
            c.mov_s(15, 0);
        }
        c.cycles += 3;
        c.g[A3][0] = sx((c.g[A3][0] as u32).wrapping_sub(0x1));
        let more = (c.g[A3][0] as i64) >= 0;
        c.g[A1][0] = sx((c.g[A1][0] as u32).wrapping_add(0x4));
        if more {
            if event_due(c) {
                deliver_event_here(c, 0x0037_5270);
            }
            continue 'gather;
        }
        break;
    }

    // ---------------------------------------------------------------
    // Epilogue: the three projection passes and the depth/scale results.
    // ---------------------------------------------------------------
    c.cycles += 318;
    c.g[AT][0] = 0x428c_0000;
    c.mtc1(1, 0); // f0 = 70.0
    c.g[V0][0] = c.g[T6][0];
    c.lwc1(5, p(c.g[GP][0] as u32, 0xffff_d80c)); // gp - 0x27f4
    c.add_s(2, 10, 0);
    c.lwc1(4, p(c.g[GP][0] as u32, 0xffff_d810)); // gp - 0x27f0
    c.sub_s(3, 14, 0);
    c.swc1(5, p(sp, 0x78));
    c.add_s(1, 13, 0);
    c.swc1(4, p(sp, 0x7c));
    c.sub_s(0, 11, 0);
    c.swc1(2, p(obj, 0x48));
    c.g[AT][0] = 0x4000_0000;
    c.mtc1(1, 6); // f6 = 2.0
    c.add_s(5, 1, 3);
    c.swc1(1, p(obj, 0x44));
    c.add_s(4, 2, 0);
    c.g[AT][0] = 0x3f80_0000;
    c.mtc1(1, 12); // f12 = 1.0
    c.sub_s(1, 1, 3);
    c.swc1(3, p(obj, 0x40));
    c.sub_s(2, 2, 0);
    c.swc1(0, p(obj, 0x4c));
    c.neg_s(5, 5);
    c.sw(p(sp, 0x54), 0u64);
    c.neg_s(4, 4);
    c.sw(p(sp, 0x58), 0u64);
    c.sw(p(sp, 0x60), 0u64);
    c.div_s(5, 5, 1);
    c.sw(p(sp, 0x68), 0u64);
    c.div_s(4, 4, 2);
    c.sw(p(sp, 0x70), 0u64);
    c.div_s(1, 6, 1);
    c.sw(p(sp, 0x74), 0u64);
    c.div_s(2, 6, 2);
    c.sw(p(sp, 0x80), 0u64);
    c.sw(p(sp, 0x84), 0u64);
    c.sw(p(sp, 0x88), 0u64);
    c.swc1(5, p(sp, 0x5c));
    c.swc1(4, p(sp, 0x6c));
    c.swc1(1, p(sp, 0x50));
    c.swc1(2, p(sp, 0x64));
    c.swc1(12, p(sp, 0x8c));
    let (t4, t5, t3) = (c.g[T4][0] as u32, c.g[T5][0] as u32, c.g[T3][0] as u32);
    let v0 = c.g[V0][0] as u32;
    let a2 = c.g[A2][0] as u32;
    transform_matrix(c, t4, t5, t3);
    copy_matrix(c, t3, v0);
    copy_matrix(c, v0, a2);

    // Second pass: light direction rows.
    c.lwc1(3, p(obj, 0x4c));
    c.lwc1(0, p(obj, 0x48));
    c.lwc1(2, p(obj, 0x40));
    c.lwc1(1, p(obj, 0x44));
    c.sub_s(0, 0, 3);
    c.neg_s(5, 2);
    c.g[AT][0] = 0xffff_ffff_bf80_0000;
    c.mtc1(1, 4); // f4 = -1.0
    c.sub_s(1, 1, 2);
    c.sw(p(sp, 0x54), 0u64);
    c.div_s(3, 3, 0);
    c.sw(p(sp, 0x58), 0u64);
    c.div_s(4, 4, 0);
    c.sw(p(sp, 0x60), 0u64);
    c.div_s(5, 5, 1);
    c.sw(p(sp, 0x68), 0u64);
    c.div_s(1, 12, 1);
    c.sw(p(sp, 0x70), 0u64);
    c.sw(p(sp, 0x74), 0u64);
    c.sw(p(sp, 0x78), 0u64);
    c.add_s(3, 3, 12);
    c.swc1(12, p(sp, 0x7c));
    c.swc1(4, p(sp, 0x64));
    c.swc1(5, p(sp, 0x5c));
    c.swc1(1, p(sp, 0x50));
    c.swc1(3, p(sp, 0x6c));
    c.sw(p(sp, 0x80), 0u64);
    c.sw(p(sp, 0x84), 0u64);
    c.sw(p(sp, 0x88), 0u64);
    c.swc1(12, p(sp, 0x8c));
    let v0 = c.g[V0][0] as u32;
    let t8 = c.g[T8][0] as u32;
    transform_matrix(c, t4, t5, t3);
    copy_matrix(c, t3, v0);
    copy_matrix(c, v0, t8);

    // Third pass: view matrix.
    c.lwc1(1, p(obj, 0x40));
    c.lwc1(0, p(obj, 0x44));
    c.lwc1(2, p(obj, 0x48));
    c.lwc1(4, p(obj, 0x4c));
    c.add_s(3, 0, 1);
    c.sub_s(0, 0, 1);
    c.g[AT][0] = 0xffff_ffff_c000_0000;
    c.mtc1(1, 5); // f5 = -2.0
    c.add_s(1, 2, 4);
    c.swc1(12, p(sp, 0x8c));
    c.sub_s(2, 2, 4);
    c.sw(p(sp, 0x54), 0u64);
    c.neg_s(3, 3);
    c.sw(p(sp, 0x58), 0u64);
    c.div_s(6, 6, 0);
    c.sw(p(sp, 0x60), 0u64);
    c.div_s(1, 1, 2);
    c.sw(p(sp, 0x68), 0u64);
    c.div_s(3, 3, 0);
    c.sw(p(sp, 0x70), 0u64);
    c.div_s(5, 5, 2);
    c.sw(p(sp, 0x74), 0u64);
    c.sw(p(sp, 0x78), 0u64);
    c.swc1(12, p(sp, 0x7c));
    c.swc1(6, p(sp, 0x50));
    c.swc1(1, p(sp, 0x6c));
    c.swc1(3, p(sp, 0x5c));
    c.swc1(5, p(sp, 0x64));
    c.sw(p(sp, 0x80), 0u64);
    c.sw(p(sp, 0x84), 0u64);
    c.sw(p(sp, 0x88), 0u64);
    let t2 = c.g[T2][0] as u32;
    transform_matrix(c, t4, t5, t3);
    copy_matrix(c, t3, v0);
    copy_matrix(c, v0, t2);

    // Depth scale and the six gathered bone rows.
    c.lwc1(1, p(obj, shadow::SCALE_IN));
    c.cvt_s_w(1, 1);
    c.g[AT][0] = 0x3f00_0000;
    c.mtc1(1, 2); // f2 = 0.5
    c.lwc1(0, p(obj, shadow::BIAS_IN));
    c.cvt_s_w(0, 0);
    c.g[AT][0] = 0x4500_0000;
    c.mtc1(1, 3); // f3 = 2048.0
    c.sw(p(obj, 0x16c), 0u64);
    c.mul_s(1, 1, 2);
    c.swc1(3, p(obj, 0x164));
    c.mul_s(0, 0, 2);
    c.sw(p(obj, shadow::DEPTH), 0u64);
    c.sw(p(obj, shadow::DEPTH + 0x4), 0u64);
    c.swc1(1, p(obj, shadow::SCALE));
    c.swc1(0, p(obj, shadow::SCALE + 0x4));
    c.swc1(3, p(obj, 0x160));
    c.sw(p(obj, 0x168), 0u64);

    // Transpose each of the three matrices in place (MMI halfword shuffles).
    let proj = c.g[A2][0] as u32;
    c.lq(9, proj);
    c.lq(8, p(proj, 0x10));
    c.lq(7, p(proj, 0x20));
    c.lq(11, p(proj, 0x30));
    c.pextlw(5, 8, 9);
    c.pextuw(4, 8, 9);
    c.pextlw(3, 11, 7);
    c.pextuw(2, 11, 7);
    c.pcpyld(9, 3, 5);
    c.pcpyud(8, 5, 3);
    c.pcpyld(7, 2, 4);
    c.pcpyud(11, 4, 2);
    c.sq(9, proj);
    c.sq(8, p(proj, 0x10));
    c.sq(7, p(proj, 0x20));
    c.sq(11, p(proj, 0x30));

    let bones = c.g[T2][0] as u32;
    c.lq(17, bones);
    c.lq(16, p(bones, 0x10));
    c.lq(15, p(bones, 0x20));
    c.lq(14, p(bones, 0x30));
    c.pextlw(13, 16, 17);
    c.pextuw(12, 16, 17);
    c.pextlw(11, 14, 15);
    c.pextuw(2, 14, 15);
    c.pcpyld(17, 11, 13);
    c.pcpyud(16, 13, 11);
    c.pcpyld(15, 2, 12);
    c.pcpyud(14, 12, 2);
    c.sq(17, bones);
    c.sq(16, p(bones, 0x10));
    c.sq(15, p(bones, 0x20));
    c.sq(14, p(bones, 0x30));

    let view = c.g[T8][0] as u32;
    c.lq(9, view);
    c.lq(8, p(view, 0x10));
    c.lq(7, p(view, 0x20));
    c.lq(6, p(view, 0x30));
    c.pextlw(5, 8, 9);
    c.pextuw(4, 8, 9);
    c.pextlw(3, 6, 7);
    c.pextuw(2, 6, 7);
    c.pcpyld(9, 3, 5);
    c.pcpyud(8, 5, 3);
    c.pcpyld(7, 2, 4);
    c.pcpyud(6, 4, 2);
    c.sq(9, view);
    c.sq(8, p(view, 0x10));
    c.sq(7, p(view, 0x20));
    c.sq(6, p(view, 0x30));

    // Restore the callee-saved registers and the frame.
    c.lq(16, p(sp, 0x120));
    c.lq(17, p(sp, 0x110));
    c.lwc1(31, p(sp, 0x188));
    c.lwc1(30, p(sp, 0x180));
    c.lwc1(29, p(sp, 0x178));
    c.lwc1(28, p(sp, 0x170));
    c.lwc1(27, p(sp, 0x168));
    c.lwc1(26, p(sp, 0x160));
    c.lwc1(25, p(sp, 0x158));
    c.lwc1(24, p(sp, 0x150));
    c.lwc1(23, p(sp, 0x148));
    c.lwc1(22, p(sp, 0x140));
    c.lwc1(21, p(sp, 0x138));
    c.lwc1(20, p(sp, 0x130));
    c.g[SP][0] = sx(p(sp, 0x190));
    abi::ret(c);
}

/// `void Irradiance_Scale(Vec4* out, const Vec4* in, float scale)` (0x3897a0):
/// scale each of ten vectors by `scale`, first into a stack buffer (through
/// VU0, as the original does), then copy the buffer to `out`.
pub fn irradiance_scale(c: &mut Cpu) {
    c.cycles += 4;
    c.g[SP][0] = sx((c.g[SP][0] as u32).wrapping_sub(0xc0));
    c.g[A2][0] = 9;
    c.g[A3][0] = sx((c.g[SP][0] as u32).wrapping_add(0xa0));
    c.g[V1][0] = c.g[SP][0];
    loop {
        c.cycles += 12;
        c.mfc1(2, 12);
        c.lqc2(4, c.g[A1][0] as u32);
        c.qmtc2(2, 3);
        c.vu0().mul(0b1111, 5, 4, Src::Bc(3, X));
        c.sqc2(5, p_4(c.g[SP][0] as u32, 0xb0));
        c.g[A2][0] = sx((c.g[A2][0] as u32).wrapping_sub(1));
        lqsp(c, 2, 0xb0);
        c.g[A1][0] = sx((c.g[A1][0] as u32).wrapping_add(0x10));
        sqsp(c, 2, 0xa0);
        c.sq(2, c.g[V1][0] as u32);
        let more = (c.g[A2][0] as i64) >= 0;
        c.g[V1][0] = sx((c.g[V1][0] as u32).wrapping_add(0x10));
        if !more {
            break;
        }
        if event_due(c) {
            deliver_event_here(c, 0x0038_97b0);
        }
    }
    c.cycles += 2;
    c.g[V1][0] = c.g[A0][0];
    c.g[V0][0] = c.g[SP][0];
    loop {
        c.cycles += 7;
        c.lq(5, c.g[V0][0] as u32);
        c.lq(6, p_4(c.g[V0][0] as u32, 0x10));
        c.sq(5, c.g[V1][0] as u32);
        c.sq(6, p_4(c.g[V1][0] as u32, 0x10));
        c.g[V0][0] = sx((c.g[V0][0] as u32).wrapping_add(0x20));
        let more = c.g[V0][0] != c.g[A3][0];
        c.g[V1][0] = sx((c.g[V1][0] as u32).wrapping_add(0x20));
        if !more {
            break;
        }
        if event_due(c) {
            deliver_event_here(c, 0x0038_97e8);
        }
    }
    c.cycles += 3;
    c.g[V0][0] = c.g[A0][0];
    let ra = c.g[RA][0] as u32;
    c.g[SP][0] = sx((c.g[SP][0] as u32).wrapping_add(0xc0));
    c.pc = ra;
}

/// `void PS2GraphicsMan_FreeAllTextures(PS2GraphicsMan* m)` (0x37c830): free
/// the first 2000 non-null texture slots through virtual slot 50.
pub fn ps2_graphics_man_free_all_textures(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 10;
        let frame = Frame::open(c, 0x40);
        sqsp(c, 18, 0x10);
        sqsp(c, 16, 0x30);
        c.g[S2][0] = c.g[A0][0];
        sqsp(c, 17, 0x20);
        c.g[S0][0] = sx((c.g[S2][0] as u32).wrapping_add(0x18f8));
        frame.save_ra(c, 0);
        c.g[S1][0] = 0;
        c.g[A1][0] = 0;
        loop {
            c.cycles += 4;
            c.g[V0][0] = Addr(c.g[S0][0] as u32).lw(c);
            c.g[S1][0] = sx((c.g[S1][0] as u32).wrapping_add(1));
            let empty = c.g[V0][0] == 0;
            c.g[S0][0] = sx((c.g[S0][0] as u32).wrapping_add(4));
            if !empty {
                c.cycles += 5;
                c.g[V0][0] = Addr(p_4(r32(c, S2), 0x10d8)).lw(c);
                c.g[A0][0] = Addr(p_4(c.g[V0][0] as u32, 0x190)).lh(c);
                c.g[V1][0] = Addr(p_4(c.g[V0][0] as u32, 0x194)).lw(c);
                let target = c.g[V1][0] as u32;
                c.g[A0][0] = abi::addu(c.g[S2][0], c.g[A0][0]);
                call::call_ptr(c, target, 0x0037_c87c)?;
            }
            c.cycles += 3;
            c.g[V0][0] = ((c.g[S1][0] as i64) < 2000) as u64;
            let more = c.g[V0][0] != 0;
            c.g[A1][0] = c.g[S1][0];
            if !more {
                break;
            }
            if event_due(c) {
                deliver_event_here(c, 0x0037_c858);
            }
        }
        c.cycles += 6;
        lqsp(c, 16, 0x30);
        lqsp(c, 17, 0x20);
        lqsp(c, 18, 0x10);
        frame.restore_ra(c, 0);
        let ra = c.g[RA][0] as u32;
        c.g[SP][0] = sx((c.g[SP][0] as u32).wrapping_add(0x40));
        c.pc = ra;
        Ok(())
    });
}

/// `void BoaderShadow_dtor(self, flags)` (0x375918): release the texture held
/// at `+0x170` (unlock the vram, then free the surface through its vtable)
/// and free the object when `flags & 1`.
pub fn boader_shadow_dtor(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 9;
        c.g[SP][0] = sx(low(c, SP).wrapping_sub(0x30));
        c.sq(16, sp_2(c).wrapping_add(0x20));
        c.sq(17, sp_2(c).wrapping_add(0x10));
        c.g[S0][0] = c.g[A0][0];
        c.sd(sp_2(c), c.g[RA][0]);
        c.g[S1][0] = c.g[A1][0];
        c.g[A1][0] = lw_r(c, S0, 0x170);
        let none = (c.g[A1][0] as i64) < 0;
        c.g[V0][0] = lw_r(c, GP, 0x2a90);
        if !none {
            c.cycles += 11;
            c.g[A0][0] = lw_r(c, V0, 0x18f4);
            callee::TEX_MAN_UNLOCK_VRAM.call(c, 0x0037_5944)?;
            c.g[A2][0] = lw_r(c, GP, 0x2a90);
            c.g[A1][0] = lw_r(c, S0, 0x170);
            c.g[V0][0] = lw_r(c, A2, 0x10d8);
            c.g[A0][0] = lh_r(c, V0, 0x190);
            c.g[V1][0] = lw_r(c, V0, 0x194);
            let target = low(c, V1);
            c.g[A0][0] = sx(low(c, A2).wrapping_add(low(c, A0)));
            call_ptr(c, target, 0x0037_5960)?;
            c.g[V0][0] = 0xffff_ffff_ffff_ffff;
            sw_r(c, S0, 0x170, c.g[V0][0]);
        }
        c.cycles += 3;
        c.g[V0][0] = c.g[S1][0] & 0x1;
        if c.g[V0][0] == 0 {
            c.lq(16, sp_2(c).wrapping_add(0x20));
        } else {
            c.cycles += 3;
            c.g[A0][0] = c.g[S0][0];
            call_ptr(c, callee::BUILTIN_DELETE_5.addr, 0x0037_597c)?;
            c.lq(16, sp_2(c).wrapping_add(0x20));
        }
        c.cycles += 4;
        c.lq(17, sp_2(c).wrapping_add(0x10));
        c.g[RA][0] = Addr(sp_2(c)).ld(c);
        let t = low(c, RA);
        c.g[SP][0] = sx(low(c, SP).wrapping_add(0x30));
        c.pc = t;
        Ok(())
    })
}

/// `void* PathArrow_ctor(self)` (0x00372aa0): set the arrow's vtable and
/// initialise the global 8-entry arrow table once.
pub fn path_arrow_ctor(c: &mut Cpu) {
    c.cycles += 5;
    c.g[V0][0] = sx(0x490000);
    c.g[V1][0] = Addr(gp(c, 0x114c)).lw(c);
    c.g[V0][0] = sx(0x490000u32.wrapping_add(0x3038));
    let done = c.g[V1][0] != 0;
    Addr(at(c, A0, 0)).sw(c, c.g[V0][0]);
    if done {
        c.cycles += 2;
        let ra = word(c, RA);
        c.g[V0][0] = c.g[A0][0];
        c.pc = ra;
        return;
    }
    c.cycles += 11;
    c.g[V0][0] = sx(0x500000);
    c.g[T0][0] = Addr(gp(c, 0x1124)).lw(c);
    c.g[V1][0] = sx(0x500000u32.wrapping_add(0x4560));
    c.g[A3][0] = Addr(gp(c, 0x1118)).lw(c);
    c.g[A2][0] = Addr(gp(c, 0x111c)).lw(c);
    c.g[T1][0] = sx(word(c, V1).wrapping_add(0x180));
    c.g[A1][0] = Addr(gp(c, 0x1120)).lw(c);
    c.g[AT][0] = 0x3f80_0000;
    c.mtc1(AT, 0);
    Addr(at(c, V1, 0x1c)).sw(c, c.g[T0][0]);
    loop {
        c.cycles += 11;
        Addr(at(c, V1, 0x10)).sw(c, c.g[A3][0]);
        Addr(at(c, V1, 0x14)).sw(c, c.g[A2][0]);
        Addr(at(c, V1, 0x18)).sw(c, c.g[A1][0]);
        c.swc1(0, at(c, V1, 0x8));
        Addr(at(c, V1, 0xc)).sw(c, 0);
        Addr(at(c, V1, 0)).sw(c, 0);
        Addr(at(c, V1, 0x4)).sw(c, 0);
        c.g[V1][0] = sx(word(c, V1).wrapping_add(0x30));
        c.g[V0][0] = ((c.g[V1][0] as i64) < (c.g[T1][0] as i64)) as u64;
        if c.g[V0][0] != 0 {
            Addr(at(c, V1, 0x1c)).sw(c, c.g[T0][0]);
            if event_due(c) {
                deliver_event_here(c, 0x0037_2ae0);
            }
            continue;
        }
        c.cycles += 2;
        c.g[V0][0] = 0x1;
        Addr(gp(c, 0x114c)).sw(c, c.g[V0][0]);
        break;
    }
    c.cycles += 2;
    let ra = word(c, RA);
    c.g[V0][0] = c.g[A0][0];
    c.pc = ra;
}

/// `void PS2GraphicsMan_SetClearColor(PS2GraphicsMan* g, float* rgb)`
/// (0x00389098): scale each channel by 255, truncate to an integer and pack
/// them into the clear colour word (`+0x6ae0`).
pub fn ps2_graphics_man_set_clear_color(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 32;
        c.g[SP][0] = sx(sp(c).wrapping_sub(0x50));
        c.sq(S0, sp(c).wrapping_add(0x30));
        c.sq(S1, sp(c).wrapping_add(0x20));
        c.sq(S2, sp(c).wrapping_add(0x10));
        c.g[S1][0] = c.g[A1][0];
        c.sd(sp(c), c.g[RA][0]);
        c.g[S2][0] = c.g[A0][0];
        c.swc1(20, sp(c).wrapping_add(0x40));
        c.g[AT][0] = 0x437f_0000;
        c.mtc1(1, 20);
        c.lwc1(12, c.g[S1][0] as u32);
        c.mul_s(12, 12, 20);
        call_ptr(c, 0x0041_39f8, 0x0038_90cc)?; // __fixunssfsi
        c.lwc1(12, (c.g[S1][0] as u32).wrapping_add(4));
        c.g[S0][0] = c.g[V0][0];
        c.mul_s(12, 12, 20);
        call_ptr(c, 0x0041_39f8, 0x0038_90dc)?; // __fixunssfsi
        c.lwc1(12, (c.g[S1][0] as u32).wrapping_add(8));
        c.g[V0][0] = sx((c.g[V0][0] as u32) << 8);
        c.g[S0][0] = c.g[S0][0] | c.g[V0][0];
        c.mul_s(12, 12, 20);
        call_ptr(c, 0x0041_39f8, 0x0038_90f0)?; // __fixunssfsi
        c.g[V0][0] = sx((c.g[V0][0] as u32) << 16);
        c.lq(S1, sp(c).wrapping_add(0x20));
        c.g[S0][0] = c.g[S0][0] | c.g[V0][0];
        c.g[RA][0] = c.ld(sp(c));
        c.sw((c.g[S2][0] as u32).wrapping_add(0x6ae0), c.g[S0][0]);
        c.lq(S0, sp(c).wrapping_add(0x30));
        c.lq(S2, sp(c).wrapping_add(0x10));
        c.lwc1(20, sp(c).wrapping_add(0x40));
        c.g[SP][0] = sx(sp(c).wrapping_add(0x50));
        abi::ret(c);
        Ok(())
    })
}

/// `void Irradiance_BuildSH(Irradiance* irr, Light* sun)` (0x00389c38): clear
/// the coefficients, add the sky's ambient entry scaled by 1.0, then add the
/// sun's camera-relative light when there is one.
pub fn irradiance_build_sh(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 12;
        c.g[SP][0] = sx(sp(c).wrapping_sub(0x30));
        c.sq(S0, sp(c).wrapping_add(0x20));
        c.sq(S1, sp(c).wrapping_add(0x10));
        c.g[S0][0] = c.g[A0][0];
        c.sd(sp(c), c.g[RA][0]);
        c.g[S1][0] = c.g[A1][0];
        call_ptr(c, 0x0038_9260, 0x0038_9c54)?; // Irradiance_Clear
        c.g[V0][0] = sx(0x0050_0000);
        c.g[A0][0] = sx((c.g[V0][0] as u32).wrapping_add(0x47f8));
        c.g[V1][0] = c.lw((c.g[A0][0] as u32).wrapping_add(4));
        if (c.g[V1][0] as i64) > 0 {
            c.cycles += 9;
            c.g[A1][0] = c.lw(gpa(c, 0x12d4));
            call_ptr(c, 0x0038_abf8, 0x0038_9c70)?; // Irradiance_GetEntry
            c.g[A2][0] = sx(0x0050_4810);
            c.g[AT][0] = 0x3f80_0000;
            c.mtc1(1, 12);
            c.g[A1][0] = c.g[V0][0];
            c.g[A0][0] = c.g[S0][0];
            call_ptr(c, 0x0038_9590, 0x0038_9c8c)?; // Irradiance_AddScaled
        }
        c.cycles += 2;
        let no_sun = c.g[S1][0] == 0;
        c.g[A0][0] = c.g[S0][0];
        if !no_sun {
            c.cycles += 4;
            c.g[AT][0] = 0x3f80_0000;
            c.mtc1(1, 12);
            c.g[A1][0] = c.g[S1][0];
            call_ptr(c, 0x0038_9cb8, 0x0038_9ca4)?; // Irradiance_AddCameraRelativeLight
        }
        c.cycles += 5;
        c.lq(S0, sp(c).wrapping_add(0x20));
        c.lq(S1, sp(c).wrapping_add(0x10));
        c.g[RA][0] = c.ld(sp(c));
        c.g[SP][0] = sx(sp(c).wrapping_add(0x30));
        abi::ret(c);
        Ok(())
    })
}

// ---------------------------------------------------------------------------
// Emitters and graphics.

/// `void mEmitter_ResetParticles(mEmitter* self)` (0x371600): reset the base
/// emitter, then clear the packed colour of every particle (the scratch
/// colour word at_2 `gp+0x28a8` is copied unaligned into each particle slot).
pub fn memitter_reset_particles(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 8;
        open(c, 0x20);
        let sp0 = spv(c);
        c.sq(16, at_2(sp0, 0x10));
        c.sd(sp0, c.g[RA][0]);
        c.g[S0][0] = c.g[A0][0];
        callee::DYNAMIC_EMITTER_RESET.call(c, 0x0037_1614)?;
        let this = c.g[S0][0];
        c.g[V0][0] = lw_at_2(c, this, 0x178);
        let count = c.g[V0][0] as i64;
        c.g[A0][0] = 0;
        if count > 0 {
            c.cycles += 2;
            c.g[A1][0] = 1;
            let a = gpa_2(c, 0x28ac);
            c.g[V0][0] = lw_at_2(c, a as u64, 0);
            loop {
                c.cycles += 2;
                if c.g[V0][0] != 0 {
                    c.g[V0][0] = lw_at_2(c, this, 0x204);
                } else {
                    c.cycles += 6;
                    let g = gpa_2(c, 0x28a8);
                    c.sb(g, 0);
                    c.sb(at_2(g, 1), 0);
                    c.sb(at_2(g, 2), 0);
                    c.sb(at_2(g, 3), 0);
                    let ga = gpa_2(c, 0x28ac);
                    c.sw(ga, c.g[A1][0]);
                    c.g[V0][0] = lw_at_2(c, this, 0x204);
                }
                c.cycles += 12;
                c.g[V1][0] = sx((c.g[A0][0] as u32) << 2);
                c.g[A0][0] = sx(at_2(c.g[A0][0] as u32, 1));
                c.g[V1][0] = sx(at_2(c.g[V1][0] as u32, c.g[V0][0] as u32));
                let t0 = gpa_2(c, 0x28a8);
                c.g[T0][0] = sx(t0);
                c.lwl(2, at_2(t0, 3));
                c.lwr(2, t0);
                let dst = c.g[V1][0] as u32;
                c.swl(2, at_2(dst, 3));
                c.swr(2, dst);
                c.g[V0][0] = lw_at_2(c, this, 0x178);
                c.g[V0][0] = ((c.g[A0][0] as i64) < (c.g[V0][0] as i64)) as u64;
                let more = c.g[V0][0] != 0;
                let ga = gpa_2(c, 0x28ac);
                c.g[V0][0] = lw_at_2(c, ga as u64, 0);
                if !more {
                    break;
                }
                if event_due(c) {
                    deliver_event_here(c, 0x0037_1628);
                }
            }
        }
        c.cycles += 4;
        c.lq(16, at_2(sp0, 0x10));
        c.g[RA][0] = c.ld(sp0);
        let ra = c.g[RA][0] as u32;
        c.g[SP][0] = sx(at_2(sp0, 0x20));
        c.pc = ra;
        Ok(())
    })
}

/// `void PS2GraphicsMan_EmitModelLighting(void* dst, void* world, u32 model,
/// void** out_dl)` (0x37e098): write a lighting packet (fixed 0x60-byte
/// header, the model's three light quadwords) and append one quadword per
/// light to the display list at_2 `*out_dl`.
pub fn ps2_graphics_man_emit_model_lighting(c: &mut Cpu) {
    c.cycles += 24;
    c.g[T0][0] = lw_at_2(c, c.g[A3][0], 0);
    c.g[V0][0] = 0x1000_000f;
    c.g[V1][0] = 0x6c03_8009;
    c.g[V1][0] = c.g[V1][0] << 32;
    c.g[A1][0] = 0x6c0a_800f;
    c.g[A1][0] = c.g[A1][0] << 32;
    let dl = c.g[T0][0] as u32;
    c.sd(dl, c.g[V0][0]);
    c.g[T1][0] = 9;
    c.sd(at_2(dl, 0x18), c.g[V1][0]);
    c.sd(at_2(dl, 8), 0);
    c.sd(at_2(dl, 0x10), 0);
    let model = c.g[A2][0] as u32;
    c.lq(2, model);
    c.sq(2, at_2(dl, 0x20));
    c.lq(3, at_2(model, 0x10));
    c.sq(3, at_2(dl, 0x30));
    c.lq(2, at_2(model, 0x20));
    c.sd(at_2(dl, 0x58), c.g[A1][0]);
    c.sq(2, at_2(dl, 0x40));
    c.sd(at_2(dl, 0x50), 0);
    c.g[T0][0] = sx(at_2(dl, 0x60));
    c.g[V1][0] = c.g[T0][0];
    loop {
        c.cycles += 7;
        let src = c.g[A0][0] as u32;
        c.lq(2, src);
        c.g[T1][0] = sx(at_2(c.g[T1][0] as u32, 0xffff_ffff));
        c.g[A0][0] = sx(at_2(src, 0x10));
        c.sq(2, c.g[V1][0] as u32);
        let more = (c.g[T1][0] as i64) >= 0;
        c.g[V1][0] = sx(at_2(c.g[V1][0] as u32, 0x10));
        if !more {
            c.cycles += 3;
            c.g[T0][0] = sx(at_2(c.g[T0][0] as u32, 0xa0));
            let ra = c.g[RA][0] as u32;
            c.sw(c.g[A3][0] as u32, c.g[T0][0]);
            c.pc = ra;
            return;
        }
        if event_due(c) {
            deliver_event_here(c, 0x0037_e0f8);
        }
    }
}

// ---------------------------------------------------------------------------
// PS2 graphics manager.

// ---------------------------------------------------------------------------
// Line strips.

/// `void LineStrip_Begin(LineStrip* ctx, void* v, void* pos)` (0x3850a8):
/// close the current strip, then start a new batch of vertices at `ctx->p`.
pub fn line_strip_begin(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 10;
        let frame = Frame::open(c, 0x40);
        frame.save(c, S0, 0x30);
        frame.save(c, S1, 0x20);
        c.g[S0][0] = c.g[A0][0];
        frame.save(c, S2, 0x10);
        c.g[S1][0] = c.g[A1][0];
        frame.save_ra(c, 0);
        c.g[V0][0] = Addr(p(r32(c, S0), 8)).lw(c);
        c.g[S2][0] = c.g[A2][0];
        if c.g[V0][0] == 0 {
            c.cycles += 5;
            c.g[V0][0] = Addr(p(r32(c, S0), 4)).lw(c);
            c.g[V1][0] = sx(r32(c, V0).wrapping_add(0x20));
            Addr(p(r32(c, S0), 8)).sw(c, c.g[V0][0]);
            Addr(p(r32(c, S0), 4)).sw(c, c.g[V1][0]);
        } else {
            c.cycles += 3;
            c.g[V0][0] = Addr(p(r32(c, S0), 0xc)).lw(c);
            if c.g[V0][0] == 0 {
                c.g[V1][0] = Addr(p(r32(c, S0), 4)).lw(c);
            } else {
                c.cycles += 2;
                c.g[A0][0] = c.g[S0][0];
                callee::LINE_STRIP_CLOSE.call(c, 0x0038_50f8)?;
                c.cycles += 1;
                c.g[V1][0] = Addr(p(r32(c, S0), 4)).lw(c);
            }
        }
        c.cycles += 14;
        c.g[A0][0] = c.g[S0][0];
        Addr(p(r32(c, S0), 0x10)).sw(c, 0);
        c.g[A1][0] = c.g[S1][0];
        c.g[V0][0] = sx(r32(c, V1).wrapping_add(0x30));
        c.g[A2][0] = c.g[S2][0];
        Addr(p(r32(c, S0), 4)).sw(c, c.g[V0][0]);
        Addr(p(r32(c, S0), 0xc)).sw(c, c.g[V1][0]);
        callee::LINE_STRIP_ADD_VERTEX.call(c, 0x0038_511c)?;
        frame.restore(c, S0, 0x30);
        frame.restore(c, S1, 0x20);
        frame.restore(c, S2, 0x10);
        frame.restore_ra(c, 0);
        frame.close(c);
        Ok(())
    })
}

/// `void* RailTube_ctor(RailTube* self, void* owner)` (0x372520): set the
/// vtable and owner; the first time, fill the 262-entry rail-vertex ring
/// with the default rail colours.
pub fn rail_tube_ctor(c: &mut Cpu) {
    c.cycles += 7;
    c.g[V0][0] = 0x0049_0000;
    c.g[V1][0] = c.lw(gp(c, 0x113c));
    c.g[V0][0] = sx(p(r32(c, V0), 0x3068));
    c.sw(at(c, A0, 4), c.g[A1][0]);
    c.sw(r32(c, A0), c.g[V0][0]);
    let ready = c.g[V1][0] != 0;
    c.sw(at(c, A0, 8), 0);
    if !ready {
        c.cycles += 9;
        c.g[V0][0] = 0x0050_0000;
        c.g[T0][0] = c.lw(gp(c, 0x10f0));
        c.g[A3][0] = c.lw(gp(c, 0x10f4));
        c.g[V1][0] = sx(p(r32(c, V0), 0x1440));
        c.g[A2][0] = c.lw(gp(c, 0x10f8));
        c.g[A1][0] = 0;
        c.g[AT][0] = 0x3f80_0000;
        c.mtc1(AT, 0);
        c.g[T1][0] = 0xff;
        loop {
            c.cycles += 9;
            c.sw(at(c, V1, 0x1c), c.g[T1][0]);
            c.g[V0][0] = c.g[A1][0] & 1;
            c.sw(at(c, V1, 0x10), c.g[T0][0]);
            c.sw(at(c, V1, 0x14), c.g[A3][0]);
            c.sw(at(c, V1, 0x18), c.g[A2][0]);
            c.swc1(0, at(c, V1, 8));
            c.sw(at(c, V1, 0xc), 0);
            let even = c.g[V0][0] == 0;
            c.sw(r32(c, V1), 0);
            if even {
                c.cycles += 1;
                c.sw(at(c, V1, 4), 0);
            } else {
                c.cycles += 2;
                c.swc1(0, at(c, V1, 4));
            }
            c.cycles += 4;
            c.g[A1][0] = sx(r32(c, A1).wrapping_add(1));
            c.g[V0][0] = ((c.g[A1][0] as i64) < 262) as u64;
            let more = c.g[V0][0] != 0;
            c.g[V1][0] = sx(at(c, V1, 0x30));
            if !more {
                c.cycles += 2;
                c.g[V0][0] = 1;
                c.sw(gp(c, 0x113c), c.g[V0][0]);
                break;
            }
            if event_due(c) {
                deliver_event_here(c, 0x0037_2560);
            }
        }
    }
    c.cycles += 2;
    let ra = r32(c, RA);
    c.g[V0][0] = c.g[A0][0];
    c.pc = ra;
}

/// `void Irradiance_AddScaled(Vec4* a, const Vec4* b, const Vec4* c, float s)`
/// (0x389590): `a[i] += b[i] * (s * c)` with the components rotated
/// (x by s*c.y, y by s*c.z, z by s*c.w, w by s*c.x) for ten vertices.
pub fn irradiance_add_scaled(c: &mut Cpu) {
    c.cycles += 10;
    c.lwc1(1, at(c, A2, 0xc));
    c.g[V0][0] = 9;
    c.lwc1(2, r32(c, A2));
    c.mul_s(7, 12, 1);
    c.lwc1(0, at(c, A2, 4));
    c.lwc1(1, at(c, A2, 8));
    c.mul_s(6, 12, 2);
    c.mul_s(5, 12, 0);
    c.mul_s(12, 12, 1);
    loop {
        c.cycles += 24;
        c.lwc1(0, r32(c, A1));
        c.g[V0][0] = sx(r32(c, V0).wrapping_sub(1));
        c.lwc1(1, r32(c, A0));
        c.mul_s(0, 0, 5);
        c.lwc1(2, at(c, A0, 4));
        c.lwc1(3, at(c, A0, 8));
        c.lwc1(4, at(c, A0, 0xc));
        c.add_s(1, 1, 0);
        c.swc1(1, r32(c, A0));
        c.lwc1(0, at(c, A1, 4));
        c.mul_s(0, 0, 12);
        c.add_s(2, 2, 0);
        c.swc1(2, at(c, A0, 4));
        c.lwc1(0, at(c, A1, 8));
        c.mul_s(0, 0, 7);
        c.add_s(3, 3, 0);
        c.swc1(3, at(c, A0, 8));
        c.lwc1(0, at(c, A1, 0xc));
        c.g[A1][0] = sx(r32(c, A1).wrapping_add(0x10));
        c.mul_s(0, 0, 6);
        c.add_s(4, 4, 0);
        c.swc1(4, at(c, A0, 0xc));
        let more = (c.g[V0][0] as i64) >= 0;
        c.g[A0][0] = sx(r32(c, A0).wrapping_add(0x10));
        if !more {
            c.cycles += 2;
            let ra = r32(c, RA);
            c.pc = ra;
            return;
        }
        if event_due(c) {
            deliver_event_here(c, 0x0038_95b8);
        }
    }
}

// ---------------------------------------------------------------------------
// Renderer.

/// `void PS2GraphicsMan_DrawShadowEdgePass(self, strips, int n, a3, a4, a5)`
/// (0x386dd0): emit every strip block with at least two vertices.
pub fn ps2_graphics_man_draw_shadow_edge_pass(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 15;
        let frame = Frame::open(c, 0x70);
        frame.save(c, S0, 0x60);
        frame.save(c, S1, 0x50);
        c.g[S0][0] = c.g[A1][0];
        frame.save(c, S2, 0x40);
        c.g[S1][0] = c.g[A2][0];
        frame.save(c, S3, 0x30);
        c.g[S2][0] = c.g[T1][0];
        frame.save(c, S4, 0x20);
        c.g[S3][0] = c.g[T0][0];
        frame.save(c, S5, 0x10);
        c.g[S4][0] = c.g[A3][0];
        c.g[S5][0] = c.g[A0][0];
        let none = (c.g[S1][0] as i64) <= 0;
        frame.save_ra(c, 0);
        if !none {
            c.cycles += 1;
            loop {
                c.cycles += 4;
                c.g[A3][0] = Addr(p(r32(c, S0), 8)).lw(c);
                c.g[V0][0] = ((c.g[A3][0] as i64) < 2) as u64;
                if c.g[V0][0] != 0 {
                    c.g[S1][0] = sx(r32(c, S1).wrapping_sub(1));
                } else {
                    c.cycles += 10;
                    c.g[A1][0] = Addr(r32(c, S0)).lw(c);
                    c.g[A0][0] = c.g[S5][0];
                    c.g[A2][0] = Addr(p(r32(c, S0), 4)).lw(c);
                    c.g[T0][0] = c.g[S4][0];
                    c.lwc1(12, p(r32(c, S0), 0xc));
                    c.g[T1][0] = c.g[S3][0];
                    c.lwc1(13, p(r32(c, S0), 0x10));
                    c.g[T2][0] = c.g[S2][0];
                    call_ptr(c, 0x0038_7ec0, 0x00386e44)?;
                    c.g[S1][0] = sx(r32(c, S1).wrapping_sub(1));
                }
                c.cycles += 2;
                let more = (c.g[S1][0] as i64) > 0;
                c.g[S0][0] = sx(p(r32(c, S0), 0x14));
                if !more {
                    break;
                }
                if event_due(c) {
                    deliver_event_here(c, 0x0038_6e10);
                }
            }
        }
        c.cycles += 9;
        frame.restore(c, S0, 0x60);
        frame.restore(c, S1, 0x50);
        frame.restore(c, S2, 0x40);
        frame.restore(c, S3, 0x30);
        frame.restore(c, S4, 0x20);
        frame.restore(c, S5, 0x10);
        frame.restore_ra(c, 0);
        frame.close(c);
        Ok(())
    })
}

/// `PS2GraphicsMan_SetBrightnessRGB(this, rgb)` (0x37c570): store the three
/// channels, each clamped to [0, 1] and scaled to 0..128, into the manager's
/// brightness words.
pub fn ps2_graphics_man_set_brightness_rgb(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 17;
        let this = abi::arg(c, 0);
        let rgb = abi::arg(c, 1);
        let frame = Frame::open(c, 0x50);
        frame.save(c, 16, 0x20);
        frame.save(c, 17, 0x10);
        c.g[S0][0] = abi::arg64(c, 1);
        frame.save_fpr(c, 21, 0x38);
        c.g[S1][0] = abi::arg64(c, 0);
        frame.save_fpr(c, 20, 0x30);
        frame.save_ra(c, 0);
        frame.save_fpr(c, 22, 0x40);

        c.g[AT][0] = 0;
        c.mtc1(0, 21);
        c.lwc1(0, rgb);
        c.g[AT][0] = 0x3f80_0000;
        c.mtc1(1, 20);
        c.c_le_s(21, 0);
        let negative = !c.fcc();
        c.mov_s(12, 21);
        if !negative {
            c.cycles += 1;
            c.min_s(12, 0, 20);
        }

        c.cycles += 10;
        c.g[AT][0] = 0x4300_0000;
        c.mtc1(1, 22);
        c.mul_s(12, 12, 22);
        call_ptr(c, addr::__FIXUNSSFSI, 0x0037_c5c8)?;
        Addr(this).off(0x59ec).sw(c, c.g[V0][0]);

        c.lwc1(0, rgb.wrapping_add(4));
        c.c_le_s(21, 0);
        let negative = !c.fcc();
        c.mov_s(12, 21);
        if !negative {
            c.cycles += 1;
            c.min_s(12, 0, 20);
        }

        c.cycles += 8;
        c.mul_s(12, 12, 22);
        call_ptr(c, addr::__FIXUNSSFSI, 0x0037_c5ec)?;
        Addr(this).off(0x59f0).sw(c, c.g[V0][0]);

        c.lwc1(0, rgb.wrapping_add(8));
        c.c_le_s(21, 0);
        let negative = !c.fcc();
        c.mov_s(12, 21);
        if !negative {
            c.cycles += 1;
            c.min_s(12, 0, 20);
        }

        c.cycles += 11;
        c.mul_s(12, 12, 22);
        call_ptr(c, addr::__FIXUNSSFSI, 0x0037_c610)?;
        Addr(this).off(0x59f4).sw(c, c.g[V0][0]);

        frame.restore(c, 16, 0x20);
        frame.restore(c, 17, 0x10);
        frame.restore_ra(c, 0);
        frame.restore_fpr(c, 22, 0x40);
        frame.restore_fpr(c, 21, 0x38);
        frame.restore_fpr(c, 20, 0x30);
        frame.close(c);
        Ok(())
    })
}

/// `cPS2GridMesh *PS2GraphicsMan_CreateGridMesh(PS2GraphicsMan *self,
/// int a1, int a2, u32 flags)` (0x37a540): allocate and construct a grid mesh;
/// when the `0x40000000` flag is set, initialise its vertex range too.
pub fn ps2_graphics_man_create_grid_mesh(c: &mut Cpu) {
    guest(c, |c| {
        c.cycles += 27;
        let frame = Frame::open(c, 0x50);
        frame.save(c, S1, 0x30);
        c.g[S1][0] = c.g[A1][0];
        frame.save(c, S0, 0x40);
        frame.save(c, S2, 0x20);
        c.g[S0][0] = c.g[A3][0];
        frame.save(c, S3, 0x10);
        c.g[S2][0] = c.g[A2][0];
        c.g[S3][0] = c.g[A0][0];
        c.g[A1][0] = 0x0049_28d8;
        c.g[A2][0] = c.g[S0][0];
        frame.save_ra(c, 0);
        c.g[A0][0] = 0x1cc;
        c.g[A3][0] = 0;
        call_ptr(c, 0x0031_7d70, 0x0037_a580)?;
        c.g[A1][0] = c.g[S1][0];
        c.g[T0][0] = c.g[S0][0];
        c.g[A0][0] = c.g[V0][0];
        c.g[A2][0] = c.g[S2][0];
        c.g[A3][0] = c.g[S3][0];
        callee::PS2_GRID_MESH_CTOR.call(c, 0x0037_a598)?;
        c.g[S1][0] = c.g[V0][0];
        c.g[V0][0] = 0x4000_0000;
        c.g[S0][0] &= c.g[V0][0];
        let no_range = c.g[S0][0] == 0;
        c.g[V0][0] = c.g[S1][0];
        if !no_range {
            c.cycles += 2;
            let mut no_mesh = false;
            if c.g[S1][0] != 0 {
                c.g[V1][0] = Addr(p_5(c.g[S1][0], 0x4)).lw(c);
            } else {
                c.cycles += 2;
                c.g[V0][0] = 0;
                no_mesh = true;
            }
            if !no_mesh {
                c.cycles += 6;
                c.g[A0][0] = Addr(p_5(c.g[V1][0], 0x10)).lh(c);
                c.g[V0][0] = Addr(p_5(c.g[V1][0], 0x14)).lw(c);
                let target = c.g[V0][0] as u32;
                c.g[A0][0] = sx((c.g[S1][0] as u32).wrapping_add(c.g[A0][0] as u32));
                call_ptr(c, target, 0x0037_a5cc)?;
                if c.g[V0][0] != 0 {
                    c.g[V0][0] = c.g[S1][0];
                } else {
                    c.cycles += 7;
                    c.g[V0][0] = Addr(p_5(c.g[S1][0], 0x4)).lw(c);
                    c.g[A1][0] = 0x3;
                    c.g[A0][0] = Addr(p_5(c.g[V0][0], 0x8)).lh(c);
                    c.g[V1][0] = Addr(p_5(c.g[V0][0], 0xc)).lw(c);
                    let target = c.g[V1][0] as u32;
                    c.g[A0][0] = sx((c.g[S1][0] as u32).wrapping_add(c.g[A0][0] as u32));
                    call_ptr(c, target, 0x0037_a5ec)?;
                    c.g[V0][0] = 0;
                }
            }
        }
        c.cycles += 7;
        frame.restore(c, S0, 0x40);
        frame.restore(c, S1, 0x30);
        frame.restore(c, S2, 0x20);
        frame.restore(c, S3, 0x10);
        frame.restore_ra(c, 0);
        frame.close(c);
        Ok(())
    })
}

/// `void func_00385AA0(void* self, u16* buf, int idx, const float* c)`
/// (0x385aa0): pack `c[1]`, `c[2]`, `c[3]`, `c[0]` (clamped to 0..1 and scaled
/// by 32) into the 16-bit PS2 colour word `buf[idx]`: `a << 15 | b << 10 |
/// g << 5 | r`, each channel saturated to 31 (alpha becomes 1 when set).
pub fn cps2_grid_mesh_pack_color(c: &mut Cpu) {
    c.cycles += 10;
    c.mtc1(0, 2); // f2 = 0.0
    c.g[T3][0] = c.g[A1][0]; // buf
    c.lwc1(1, p(c.g[A3][0] as u32, 4)); // f1 = c[1]
    c.g[T2][0] = c.g[A2][0]; // idx
    c.g[AT][0] = 0x3f80_0000;
    c.mtc1(1, 3); // f3 = 1.0
    c.c_le_s(2, 1); // 0 <= c[1]
    c.mov_s(0, 2); // f0 = 0.0
    if c.fcc() {
        c.cycles += 1;
        c.min_s(0, 1, 3); // f0 = min(c[1], 1.0)
    }

    c.cycles += 10;
    c.g[AT][0] = 0x4200_0000;
    c.mtc1(1, 5); // f5 = 32.0
    c.mov_s(4, 2); // f4 = 0.0
    c.lwc1(1, p(c.g[A3][0] as u32, 8)); // f1 = c[2]
    c.mul_s(0, 0, 5); // f0 *= 32
    c.c_le_s(2, 1);
    c.cvt_w_s(6, 0); // f6 = (int)f0
    c.mfc1(2, 6); // v0 = f6
    let t = !c.fcc();
    c.g[T1][0] = c.g[V0][0] & 0xff; // r
    if !t {
        c.cycles += 1;
        c.min_s(4, 1, 3); // f4 = min(c[2], 1.0)
    }

    c.cycles += 8;
    c.mul_s(0, 4, 5); // f0 = f4 * 32
    c.lwc1(1, p(c.g[A3][0] as u32, 0xc)); // f1 = c[3]
    c.mov_s(4, 2);
    c.c_le_s(2, 1);
    c.cvt_w_s(6, 0);
    c.mfc1(2, 6);
    let t = !c.fcc();
    c.g[T0][0] = c.g[V0][0] & 0xff; // g
    if !t {
        c.cycles += 1;
        c.min_s(4, 1, 3);
    }

    c.cycles += 8;
    c.mul_s(0, 4, 5);
    c.lwc1(1, c.g[A3][0] as u32); // f1 = c[0]
    c.mov_s(4, 2);
    c.c_le_s(2, 1);
    c.cvt_w_s(2, 0);
    c.mfc1(2, 2);
    let t = !c.fcc();
    c.g[A3][0] = c.g[V0][0] & 0xff; // b
    if !t {
        c.cycles += 1;
        c.min_s(4, 1, 3);
    }

    c.cycles += 23;
    c.mul_s(0, 4, 5); // f0 = f4 * 32
    c.g[A1][0] = 0x1f;
    c.g[V1][0] = (c.g[A3][0] < 0x20) as u64;
    c.g[V0][0] = 0x1;
    if c.g[V1][0] == 0 {
        c.g[A3][0] = c.g[A1][0];
    }
    c.g[A0][0] = (c.g[T0][0] < 0x20) as u64;
    c.cvt_w_s(1, 0);
    c.mfc1(3, 1); // t3 = (int)(clamp(c[0]) * 32)
    if c.g[A0][0] == 0 {
        c.g[T0][0] = c.g[A1][0];
    }
    c.g[A3][0] = sx((c.g[A3][0] as u32) << 10);
    c.g[T0][0] = sx((c.g[T0][0] as u32) << 5);
    c.g[A2][0] = (c.g[T1][0] < 0x20) as u64;
    c.g[A0][0] = sx((c.g[T2][0] as u32) << 1);
    c.g[V1][0] = c.g[V1][0] & 0xff;
    if c.g[A2][0] == 0 {
        c.g[T1][0] = c.g[A1][0];
    }
    if c.g[V1][0] == 0 {
        c.g[V0][0] = c.g[V1][0];
    }
    c.g[A0][0] = sx((c.g[A0][0] as u32).wrapping_add(c.g[T3][0] as u32));
    c.g[V0][0] = sx((c.g[V0][0] as u32) << 15);
    c.g[V0][0] = c.g[V0][0] | c.g[A3][0];
    c.g[V0][0] = c.g[V0][0] | c.g[T0][0];
    c.g[V0][0] = c.g[V0][0] | c.g[T1][0];
    c.sh(c.g[A0][0] as u32, c.g[V0][0]);
    abi::ret(c);
}

/// `void LineStrip_Finish(PktBuilder* self, int flags)` (0x384e50): close
/// the strip's packet: flush the open block, emit the two-quadword draw kick
/// from the current node (batching under 2600 vertices), advance the
/// cursors, and optionally release the builder's packet.
pub fn line_strip_finish(c: &mut Cpu) {
    'b_384fa8: {
        c.cycles += 8;
        c.g[SP][0] = sx((c.g[SP][0] as u32).wrapping_sub(0x30));
        c.sq(16, c.pa(SP, 0x20));
        c.sq(17, c.pa(SP, 0x10));
        c.g[S0][0] = c.g[A0][0];
        c.std(SP, 0, c.g[RA][0]);
        c.g[V0][0] = c.ldw_2(S0, 0x8);
        let t = c.g[V0][0] == 0u64;
        c.g[S1][0] = c.g[A1][0];
        if t {
            break 'b_384fa8;
        } else {
            'b_384e88: {
                c.cycles += 3;
                c.g[V0][0] = c.ldw_2(S0, 0xc);
                if c.g[V0][0] == 0u64 {
                    c.g[A0][0] = c.ldw_2(S0, 0x8);
                    break 'b_384e88;
                } else {
                    c.cycles += 3;
                    c.g[RA][0] = sx(0x00384e84);
                    c.pc = 0x00384dc0;
                    call_indirect(c, 0x00384dc0);
                    if c.pc != 0x00384e84 {
                        return;
                    }
                    c.g[A0][0] = c.ldw_2(S0, 0x8);
                    break 'b_384e88;
                }
            }
            'b_384f94: {
                c.cycles += 34;
                c.g[A3][0] = 0x10000000;
                c.g[V0][0] = c.ldw_2(S0, 0x4);
                c.g[A2][0] = 0x50000000;
                c.g[A1][0] = 0xfff0000;
                c.g[V0][0] = sx((c.g[V0][0] as u32).wrapping_sub(c.g[A0][0] as u32));
                c.g[A1][0] = c.g[A1][0] | 0xffff;
                c.g[V1][0] = sx((c.g[V0][0] as u32) >> 31);
                c.g[V0][0] = sx(((c.g[V0][0] as u32) as i32 >> 3) as u32);
                c.g[V0][0] = sx((c.g[V0][0] as u32).wrapping_add(c.g[V1][0] as u32));
                c.g[V0][0] = sx(((c.g[V0][0] as u32) as i32 >> 1) as u32);
                c.g[V1][0] = sx((c.g[V0][0] as u32).wrapping_sub(0x1));
                c.g[V1][0] = c.g[V1][0] | c.g[A3][0];
                c.g[V0][0] = sx((c.g[V0][0] as u32).wrapping_sub(0x2));
                c.std(A0, 0, c.g[V1][0]);
                c.g[V0][0] = c.g[V0][0] | c.g[A2][0];
                c.g[V0][0] = c.g[V0][0] << 32;
                c.g[V1][0] = c.ldw_2(S0, 0x8);
                c.std(V1, 0x8, 0u64);
                c.g[A0][0] = c.ldw_2(S0, 0x8);
                c.std(A0, 0x10, 0u64);
                c.g[V1][0] = c.ldw_2(S0, 0x8);
                c.std(V1, 0x18, c.g[V0][0]);
                c.g[V0][0] = c.ldw_2(S0, 0x4);
                c.g[A0][0] = c.ldw_2(S0, 0x8);
                c.g[V1][0] = c.ldw_2(GP, 0x2a90);
                c.g[T1][0] = c.g[V0][0] & c.g[A1][0];
                c.g[T2][0] = c.g[A0][0] & c.g[A1][0];
                c.stw_2(S0, 0x4, c.g[T1][0]);
                c.stw_2(S0, 0x8, c.g[T2][0]);
                c.g[A3][0] = c.ldw_2(V1, 0x18f0);
                c.g[V0][0] = c.ldw_2(A3, 0);
                c.g[V0][0] = ((c.g[V0][0] as i64) < 2600i64) as u64;
                let t = c.g[V0][0] == 0u64;
                c.g[T0][0] = c.ldw_2(V1, 0xe84);
                if t {
                    break 'b_384f94;
                } else {
                    c.cycles += 33;
                    c.g[A1][0] = 0x60000;
                    c.g[A0][0] = c.ldw_2(T0, 0x8);
                    c.g[A1][0] = c.g[A1][0] | 0x8000;
                    c.g[V1][0] = 0xffffffffffffffe0;
                    c.g[A1][0] = sx((c.g[A3][0] as u32).wrapping_add(c.g[A1][0] as u32));
                    c.g[A0][0] = c.g[A0][0] & c.g[V1][0];
                    c.g[V0][0] = c.ldw_2(A1, 0x1cc4);
                    c.g[A2][0] = sx((c.g[A3][0] as u32).wrapping_add(0x80));
                    c.g[V1][0] = 0x30000000;
                    c.g[V0][0] = c.g[V0][0] & 0x1f;
                    c.g[A2][0] = c.g[A2][0] | c.g[V1][0];
                    c.g[A0][0] = c.g[A0][0] | c.g[V0][0];
                    c.stw_2(T0, 0x8, c.g[A0][0]);
                    c.g[V1][0] = c.ldw_2(A3, 0);
                    c.g[A0][0] = c.ldw_2(A1, 0x1cc0);
                    c.g[V0][0] = sx((c.g[V1][0] as u32) << 7);
                    c.g[V1][0] = sx((c.g[V1][0] as u32).wrapping_add(0x1));
                    c.g[V0][0] = sx((c.g[V0][0] as u32).wrapping_add(c.g[A2][0] as u32));
                    c.stw_2(A3, 0, c.g[V1][0]);
                    c.ldl(3, c.pa(T0, 0x7));
                    c.ldr(3, c.pa(T0, 0));
                    c.ldl(5, c.pa(T0, 0xf));
                    c.ldr(5, c.pa(T0, 0x8));
                    c.g[A2][0] = c.ldw_2(T0, 0x10);
                    c.sdl(3, c.pa(V0, 0x7));
                    c.sdr(3, c.pa(V0, 0));
                    c.sdl(5, c.pa(V0, 0xf));
                    c.sdr(5, c.pa(V0, 0x8));
                    c.stw_2(V0, 0x10, c.g[A2][0]);
                    c.stw_2(V0, 0x14, c.g[T2][0]);
                    c.stw_2(V0, 0x18, c.g[T1][0]);
                    c.sth_2(V0, 0x1c, c.g[A0][0]);
                    c.sth_2(V0, 0x1e, 0u64);
                    break 'b_384f94;
                }
            }
            c.cycles += 5;
            c.g[V0][0] = c.ldw_2(S0, 0x4);
            c.g[V1][0] = c.ldw_2(S0, 0);
            c.g[V0][0] = sx((c.g[V0][0] as u32).wrapping_add(0x10));
            c.stw_2(S0, 0x4, c.g[V0][0]);
            c.stw_2(V1, 0, c.g[V0][0]);
            break 'b_384fa8;
        }
    }
    'b_384fc0: {
        c.cycles += 3;
        c.g[V0][0] = c.g[S1][0] & 0x1;
        if c.g[V0][0] == 0u64 {
            c.lq(16, c.pa(SP, 0x20));
            break 'b_384fc0;
        } else {
            c.cycles += 3;
            c.g[RA][0] = sx(0x00384fbc);
            c.g[A0][0] = c.g[S0][0];
            c.pc = 0x00317e50;
            call_indirect(c, 0x00317e50);
            if c.pc != 0x00384fbc {
                return;
            }
            c.lq(16, c.pa(SP, 0x20));
            break 'b_384fc0;
        }
    }
    c.cycles += 4;
    c.lq(17, c.pa(SP, 0x10));
    c.g[RA][0] = c.ldd(SP, 0);
    let ra = c.g[RA][0] as u32;
    c.g[SP][0] = sx((c.g[SP][0] as u32).wrapping_add(0x30));
    c.pc = ra;
    return;
}

// ---------------------------------------------------------------------------
// Bézier patch cache tessellation.

/// Load the patch's 4x4 grid of control points (16 quads from `p`) into
/// vf1..vf16.
pub(crate) fn load_control_points(c: &mut Cpu, p: u32) {
    for k in 0..16u32 {
        c.lqc2(1 + k as usize, p.wrapping_add(0x10 * k));
    }
}

/// The curve of one parameter row: weights from the basis entry at_2 `w`
/// (vf17) applied to each column of control points, giving the curve's
/// four control points in vf18..vf21.
pub(crate) fn basis_row(c: &mut Cpu, w: u32) {
    c.lqc2(17, w);
    for (k, out) in (18u8..=21).enumerate() {
        let col = 1 + 4 * k as u8;
        c.vu0().mula(0b1111, col, Src::Bc(17, X));
        c.vu0().madda(0b1111, col + 1, Src::Bc(17, Y));
        c.vu0().madda(0b1111, col + 2, Src::Bc(17, Z));
        c.vu0().madd(0b1111, out, col + 3, Src::Bc(17, W));
    }
}

/// A point of the row curve (vf18..vf21): weights from the basis entry at_2
/// `w` (vf22); the point in vf23.
pub(crate) fn curve_point(c: &mut Cpu, w: u32) {
    c.lqc2(22, w);
    c.vu0().mula(0b1111, 18, Src::Bc(22, X));
    c.vu0().madda(0b1111, 19, Src::Bc(22, Y));
    c.vu0().madda(0b1111, 20, Src::Bc(22, Z));
    c.vu0().madd(0b1111, 23, 21, Src::Bc(22, W));
}

/// The end of a row (both tessellators): `v1 = v0 (row + 1)`, `v0 = row
/// < n`; true when another row follows, `v0 = row << 4` then.
pub(crate) fn next_row(c: &mut Cpu, n_reg: usize) -> bool {
    c.cycles += 4;
    c.g[V1][0] = c.g[V0][0];
    c.g[V0][0] = ((c.g[V1][0] as i64) < (c.g[n_reg][0] as i64)) as u64;
    let more = c.g[V0][0] != 0;
    c.g[V0][0] = sx(r32(c, V1) << 4);
    more
}

/// `void BezierPatchCache_TessPositions(BezierPatchCache* cache,
/// BezierPatch* patch, Vec3* out, int lod)` (0x374180): evaluate the bicubic
/// patch (control points at_2 patch+0x40) on the LOD's `n x n` parameter grid
/// (basis table `cache->basis[lod]` at_2 +0x190, `n = cache->count[lod]` at_2
/// +0x19c, one quad of weights per parameter) and write the positions as
/// packed vec3s, row by row. The quad goes through a 16-byte stack slot
/// (`ldl/ldr` + `lw`, then `sdl/sdr` + `sw`).
pub fn bezier_patch_cache_tess_positions(c: &mut Cpu) {
    const ROW_HEAD: u32 = 0x0037_41e8;
    const POINT_HEAD: u32 = 0x0037_4240;
    c.cycles += 25;
    c.g[A3][0] = sx(r32(c, A3) << 2);
    c.g[SP][0] = sx(sp(c).wrapping_sub(0x10));
    c.g[V0][0] = sx(r32(c, A0).wrapping_add(r32(c, A3)));
    c.g[A1][0] = sx(r32(c, A1).wrapping_add(0x40));
    c.g[A0][0] = c.g[V0][0];
    c.g[T0][0] = c.lw(at(c, V0, 0x190)); // basis
    c.g[A3][0] = c.lw(at(c, A0, 0x19c)); // n
    load_control_points(c, r32(c, A1));
    c.g[V1][0] = 0;
    if (c.g[A3][0] as i64) > 0 {
        c.cycles += 1;
        c.g[V0][0] = sx(r32(c, V1) << 4);
        loop {
            c.cycles += 20;
            c.g[V0][0] = sx(r32(c, T0).wrapping_add(r32(c, V0)));
            basis_row(c, r32(c, V0));
            let empty = (c.g[A3][0] as i64) <= 0;
            c.g[V0][0] = sx(r32(c, V1).wrapping_add(1));
            if !empty {
                c.cycles += 2;
                c.g[A0][0] = c.g[T0][0];
                c.g[V1][0] = c.g[A3][0];
                loop {
                    c.cycles += 16;
                    curve_point(c, r32(c, A0));
                    let tmp = sp(c);
                    c.sqc2(23, tmp);
                    c.g[V1][0] = sx(r32(c, V1).wrapping_sub(1));
                    c.ldl(A1, tmp.wrapping_add(7));
                    c.ldr(A1, tmp);
                    c.g[T1][0] = c.lw(tmp.wrapping_add(8));
                    let out = r32(c, A2);
                    c.sdl(A1, out.wrapping_add(7));
                    c.sdr(A1, out);
                    c.g[A0][0] = sx(r32(c, A0).wrapping_add(0x10));
                    c.sw(out.wrapping_add(8), c.g[T1][0]);
                    let more = c.g[V1][0] != 0;
                    c.g[A2][0] = sx(out.wrapping_add(0xc));
                    if !more {
                        break;
                    }
                    if event_due(c) {
                        deliver_event_here(c, POINT_HEAD);
                    }
                }
            }
            if !next_row(c, A3) {
                break;
            }
            if event_due(c) {
                deliver_event_here(c, ROW_HEAD);
            }
        }
    }
    c.cycles += 2;
    c.g[SP][0] = sx(sp(c).wrapping_add(0x10));
    ret(c);
}

/// `void BezierPatchCache_TessPositionsAlt(BezierPatchCache* cache,
/// BezierPatch* patch, Vec3* out, int lod)` (0x374518): two passes over the
/// LOD's `n x n` grid (`n` at_2 +0x19c, value basis at_2 +0x190, derivative
/// basis at_2 +0x310, per LOD). Pass 1 writes one tangent (derivative-basis
/// rows, value-basis points) to `out`; pass 2 evaluates the other tangent
/// (value-basis rows, derivative-basis points) and replaces each entry
/// with the normalised cross product of the two (left unnormalised when
/// its length is 0): the patch normals.
pub fn bezier_patch_cache_tess_positions_alt(c: &mut Cpu) {
    const DU_ROW_HEAD: u32 = 0x0037_4590;
    const DU_POINT_HEAD: u32 = 0x0037_45e8;
    const DV_ROW_HEAD: u32 = 0x0037_4648;
    const DV_POINT_HEAD: u32 = 0x0037_46b0;
    c.cycles += 28;
    c.g[A3][0] = sx(r32(c, A3) << 2);
    c.g[SP][0] = sx(sp(c).wrapping_sub(0x30));
    c.g[V1][0] = sx(r32(c, A0).wrapping_add(r32(c, A3)));
    c.g[A1][0] = sx(r32(c, A1).wrapping_add(0x40));
    c.g[V0][0] = c.g[V1][0];
    c.g[T2][0] = c.lw(at(c, V1, 0x310)); // derivative basis
    c.g[A0][0] = c.g[V0][0];
    c.g[T0][0] = c.lw(at(c, V0, 0x19c)); // n
    c.g[T1][0] = c.lw(at(c, A0, 0x190)); // value basis
    c.g[A3][0] = c.g[A2][0];
    load_control_points(c, r32(c, A1));
    c.g[V1][0] = 0;
    // Pass 1: d/du into out.
    if (c.g[T0][0] as i64) > 0 {
        c.cycles += 2;
        c.g[V0][0] = sx(r32(c, V1) << 4);
        loop {
            c.cycles += 20;
            c.g[V0][0] = sx(r32(c, T2).wrapping_add(r32(c, V0)));
            basis_row(c, r32(c, V0));
            let empty = (c.g[T0][0] as i64) <= 0;
            c.g[V0][0] = sx(r32(c, V1).wrapping_add(1));
            if !empty {
                c.cycles += 2;
                c.g[A0][0] = c.g[T1][0];
                c.g[V1][0] = c.g[T0][0];
                loop {
                    c.cycles += 16;
                    curve_point(c, r32(c, A0));
                    let tmp = sp(c);
                    c.sqc2(23, tmp);
                    c.g[V1][0] = sx(r32(c, V1).wrapping_sub(1));
                    c.ldl(A1, tmp.wrapping_add(7));
                    c.ldr(A1, tmp);
                    c.g[T3][0] = c.lw(tmp.wrapping_add(8));
                    let out = r32(c, A3);
                    c.sdl(A1, out.wrapping_add(7));
                    c.sdr(A1, out);
                    c.g[A0][0] = sx(r32(c, A0).wrapping_add(0x10));
                    c.sw(out.wrapping_add(8), c.g[T3][0]);
                    let more = c.g[V1][0] != 0;
                    c.g[A3][0] = sx(out.wrapping_add(0xc));
                    if !more {
                        break;
                    }
                    if event_due(c) {
                        deliver_event_here(c, DU_POINT_HEAD);
                    }
                }
            }
            if !next_row(c, T0) {
                break;
            }
            if event_due(c) {
                deliver_event_here(c, DU_ROW_HEAD);
            }
        }
    }
    // Pass 2: d/dv, crossed with d/du, normalised.
    c.cycles += 3;
    c.g[A3][0] = c.g[A2][0];
    c.g[V1][0] = 0;
    if (c.g[T0][0] as i64) > 0 {
        c.cycles += 1;
        c.g[V0][0] = sx(r32(c, V1) << 4);
        loop {
            c.cycles += 20;
            c.g[V0][0] = sx(r32(c, T1).wrapping_add(r32(c, V0)));
            basis_row(c, r32(c, V0));
            let empty = (c.g[T0][0] as i64) <= 0;
            c.g[V0][0] = sx(r32(c, V1).wrapping_add(1));
            if !empty {
                c.cycles += 6;
                c.mtc1(0, 9); // f9 = 0
                c.g[A0][0] = c.g[T2][0];
                c.g[AT][0] = 0x3f80_0000;
                c.mtc1(AT, 8); // f8 = 1
                c.g[V1][0] = c.g[T0][0];
                loop {
                    c.cycles += 34;
                    curve_point(c, r32(c, A0));
                    normal_at(c);
                    c.cycles += 10;
                    let tmp = sp(c);
                    c.ldl(A1, tmp.wrapping_add(0x17));
                    c.ldr(A1, tmp.wrapping_add(0x10));
                    c.g[A2][0] = c.lw(tmp.wrapping_add(0x18));
                    let out = r32(c, A3);
                    c.sdl(A1, out.wrapping_add(7));
                    c.sdr(A1, out);
                    c.sw(out.wrapping_add(8), c.g[A2][0]);
                    c.g[A0][0] = sx(r32(c, A0).wrapping_add(0x10));
                    c.g[V1][0] = sx(r32(c, V1).wrapping_sub(1));
                    let more = c.g[V1][0] != 0;
                    c.g[A3][0] = sx(out.wrapping_add(0xc));
                    if !more {
                        break;
                    }
                    if event_due(c) {
                        deliver_event_here(c, DV_POINT_HEAD);
                    }
                }
            }
            if !next_row(c, T0) {
                break;
            }
            if event_due(c) {
                deliver_event_here(c, DV_ROW_HEAD);
            }
        }
    }
    c.cycles += 2;
    c.g[SP][0] = sx(sp(c).wrapping_add(0x30));
    ret(c);
}

/// Pass 2 of `TessPositionsAlt` at_2 one grid entry: `a = out[i]` (d/du),
/// `b = vf23` (d/dv, stored at_2 sp+0); `n = a × b` at_2 sp+0x20, then
/// `n / |n|` (or `n` when `|n| == 0`) at_2 sp+0x10..0x18 (f9 = 0, f8 = 1).
pub(crate) fn normal_at(c: &mut Cpu) {
    let tmp = sp(c);
    let out = r32(c, A3);
    c.sqc2(23, tmp);
    c.lwc1(1, out.wrapping_add(8)); // a.z
    c.lwc1(6, out); // a.x
    c.lwc1(4, tmp.wrapping_add(4)); // b.y
    c.lwc1(0, tmp.wrapping_add(8)); // b.z
    c.lwc1(3, out.wrapping_add(4)); // a.y
    c.mul_s(7, 4, 1);
    c.lwc1(2, tmp); // b.x
    c.mul_s(5, 0, 6);
    c.mul_s(0, 0, 3);
    c.mul_s(1, 2, 1);
    c.mul_s(2, 2, 3);
    c.sub_s(7, 7, 0); // f7 = b.y a.z - b.z a.y
    c.sub_s(5, 5, 1); // f5 = b.z a.x - b.x a.z
    c.mul_s(4, 4, 6);
    c.mul_s(0, 7, 7);
    c.swc1(7, tmp.wrapping_add(0x20));
    c.mul_s(3, 5, 5);
    c.swc1(5, tmp.wrapping_add(0x24));
    c.sub_s(2, 2, 4); // f2 = b.x a.y - b.y a.x
    c.add_s(0, 0, 3);
    c.mul_s(1, 2, 2);
    c.swc1(2, tmp.wrapping_add(0x28));
    c.add_s(0, 0, 1);
    c.sqrt_s(0, 0);
    c.c_eq_s(0, 9);
    if c.fcc() {
        c.swc1(7, tmp.wrapping_add(0x10));
        c.cycles += 2;
        c.swc1(5, tmp.wrapping_add(0x14));
        c.swc1(2, tmp.wrapping_add(0x18));
    } else {
        c.cycles += 8;
        c.div_s(0, 8, 0); // 1 / |n|
        c.mul_s(1, 2, 0);
        c.mul_s(2, 7, 0);
        c.mul_s(0, 5, 0);
        c.swc1(1, tmp.wrapping_add(0x18));
        c.swc1(2, tmp.wrapping_add(0x10));
        c.swc1(0, tmp.wrapping_add(0x14));
    }
}

pub(crate) mod ortho {

    /// Display object: `lh +0x50`/`+0x58` this-deltas, methods at
    /// `+0x54` (screen width) and `+0x5c` (screen height).
    pub const DISPLAY: u32 = 0x10d8;

    pub const CUR_VIEW: u32 = 0x10dc;

    /// Drawing mode (0x31 selects the large depth range).
    pub const MODE: u32 = 0x5a40;

    /// `sPtView views[]`, 0x230 bytes each: viewport x, y, w, h at +0..+0xc,
    /// near/far at +0x10/+0x14, the ortho flag at +0x20.
    pub const VIEWS: u32 = 0x6d20;

    pub const VIEW_STRIDE: u32 = 0x230;

    pub const VIEW_NEAR: u32 = 0x10;

    pub const VIEW_FAR: u32 = 0x14;

    pub const VIEW_ORTHO: u32 = 0x20;

    /// Screen projection matrix (rows 0x6af0..0x6b2c) and viewport quads.
    pub const SCREEN_MAT: u32 = 0x6af0;

    pub const VIEWPORT_MIN: u32 = 0x6b70;

    pub const VIEWPORT_MAX: u32 = 0x6b80;

    /// Set when the view matrices are current (cleared: rebuild).
    pub const MATS_READY: u32 = 0x6b90;

    /// Clip-space matrix (0x57c0), projection (0x5860), clip quads (0x5840,
    /// 0x5850), viewport half sizes and offsets (0x58e0, 0x58f0).
    pub const LOCAL_MAT: u32 = 0x57c0;

    pub const PROJ_MAT: u32 = 0x5860;

    /// gp-relative `.lit4` constants.
    pub const GP_BIAS: u32 = 0x2794;

    pub const GP_BIAS_BIG: u32 = 0x2790;

    pub const GP_DEPTH_BIG: u32 = 0x278c;

    pub const GP_DEPTH_FAR_BIG: u32 = 0x2788;

    pub const GP_DEPTH: u32 = 0x2784;

    pub const GP_DEPTH_FAR: u32 = 0x2780;

    pub const GP_PIXEL_OFFSET: u32 = 0x277c;

    pub const GP_5910: u32 = 0x2778;

    pub const GP_5920: u32 = 0x2774;

    pub const GP_592C: u32 = 0x2770;
}

pub(crate) const SET_SCISSOR_CLAMPED: Callee = Callee {
    addr: 0x0037_6938,
    f: ee::s12::PS2GraphicsMan_SetScissorClamped,
};

/// The display's `this` adjusted by the halfword delta at `delta_off`, and
/// the method pointer at `delta_off + 4` (`a0`/`v0` as the call expects);
/// leaves the display pointer in v1.
pub(crate) fn set_ortho_display_method(c: &mut Cpu, gfx: u32, delta_off: u32) -> u32 {
    use crate::guest::Addr;
    let disp = Addr(gfx).off(ortho::DISPLAY).lw(c);
    c.g[V1][0] = disp;
    let delta = Addr(disp as u32).off(delta_off).lh(c);
    c.g[A0][0] = delta;
    let method = Addr(disp as u32).off(delta_off + 4).lw(c);
    c.g[V0][0] = method;
    c.g[A0][0] = sx(gfx.wrapping_add(delta as u32));
    method as u32
}

/// gcc's `(float)(u32)` of a 64-bit result (calls 3 and 4): halve-or-1 and
/// double when the value reads negative. Leaves v0/v1 as the original.
pub(crate) fn set_ortho_u64_to_float(c: &mut Cpu) -> crate::ps2f::FpuF32 {
    use crate::ps2f::FpuF32;
    let negative = (c.g[V0][0] as i64) < 0;
    c.g[V1][0] = sx((c.g[V0][0] as u32) >> 1);
    if negative {
        c.cycles += 5;
        c.g[V0][0] = (c.g[V0][0] & 1) | c.g[V1][0];
        let h = FpuF32::from_i32(c.g[V0][0] as u32 as i32);
        h + h
    } else {
        c.cycles += 4;
        FpuF32::from_i32(c.g[V0][0] as u32 as i32)
    }
}

/// `(float)(u32)(v << 3)` of a 32-bit result (calls 1 and 2): the shifted
/// value halved and doubled when its sign bit is set. Leaves v0 as the
/// original; returns the value and whether the halving path was taken.
pub(crate) fn set_ortho_times8_to_float(c: &mut Cpu) -> (crate::ps2f::FpuF32, bool) {
    use crate::ps2f::FpuF32;
    c.g[V0][0] = sx((c.g[V0][0] as u32) << 3);
    if (c.g[V0][0] as i64) < 0 {
        c.g[V0][0] = sx((c.g[V0][0] as u32) >> 1);
        let h = FpuF32::from_i32(c.g[V0][0] as u32 as i32);
        (h + h, true)
    } else {
        (FpuF32::from_i32(c.g[V0][0] as u32 as i32), false)
    }
}

/// `void PS2GraphicsMan_SetOrtho(PS2GraphicsMan* g, float left, float top,
/// float width, float height, float near, float far)` (0x377458): switch
/// the current view to an orthographic projection. Marks the view ortho with
/// its near/far, builds the screen matrix and viewport quads from the view
/// rectangle and the display's size (both centred on the GS 2048 offset),
/// builds the clip-space and projection matrices with the guard-band ratios,
/// mode-dependent depth constants, then clamps the scissor to the viewport
/// and resets the fog/texture constants at 0x5910..0x592c.
pub fn ps2_graphics_man_set_ortho(c: &mut Cpu) {
    use crate::{abi, guest::Addr, ps2f::FpuF32};
    use ortho::*;
    guest(c, |c| {
        c.cycles += 42;
        let frame = Frame::open(c, 0x90);
        let sp0 = sp(c);
        let left = FpuF32(c.f[12]);
        let top = FpuF32(c.f[13]);
        let width = FpuF32(c.f[14]);
        let height = FpuF32(c.f[15]);
        let near = FpuF32(c.f[16]);
        let far = FpuF32(c.f[17]);
        c.g[V0][0] = 1;
        frame.save(c, S0, 0x20);
        c.g[A1][0] = 0x31;
        for (f, off) in [
            (28, 0x70),
            (27, 0x68),
            (24, 0x50),
            (22, 0x40),
            (31, 0x88),
            (30, 0x80),
            (29, 0x78),
            (26, 0x60),
            (25, 0x58),
            (23, 0x48),
            (21, 0x38),
            (20, 0x30),
        ] {
            frame.save_fpr(c, f, off);
        }
        frame.save_ra(c, 0x10);
        c.g[S0][0] = c.g[A0][0];
        c.g[A0][0] = VIEW_STRIDE as u64;
        abi::set_fpr(c, 27, width);
        abi::set_fpr(c, 24, near);
        abi::set_fpr(c, 22, far);
        abi::set_fpr(c, 28, height);
        let gfx = c.g[S0][0] as u32;

        // Mark the current view orthographic with its depth range.
        c.g[V1][0] = Addr(gfx).off(CUR_VIEW).lw(c);
        Addr(sp0).write_fpu(c, left);
        c.mult(0, V1, V1, A0);
        Addr(sp0).off(4).write_fpu(c, top);
        let view = gfx.wrapping_add((c.g[V1][0] as u32).wrapping_add(VIEWS));
        c.g[V1][0] = sx(view);
        let ortho_flag = c.g[V0][0];
        Addr(view).off(VIEW_ORTHO).sw(c, ortho_flag);
        Addr(view).off(VIEW_FAR).write_fpu(c, far);
        Addr(view).off(VIEW_NEAR).write_fpu(c, near);

        // The view rectangle and the depth bias for the mode.
        c.g[V0][0] = Addr(gfx).off(CUR_VIEW).lw(c);
        c.g[V1][0] = Addr(gfx).off(MODE).lw(c);
        c.mult(0, A2, V0, A0);
        c.g[V0][0] = sx((c.g[A2][0] as u32).wrapping_add(gfx));
        let rect = Addr((c.g[V0][0] as u32).wrapping_add(VIEWS));
        let vh = rect.off(0xc).read_fpu(c);
        let vx = rect.read_fpu(c);
        let vy = rect.off(4).read_fpu(c);
        let gp = c.g[GP][0] as u32;
        let mut bias = Addr(gp.wrapping_sub(GP_BIAS)).read_fpu(c);
        let vw = rect.off(8).read_fpu(c);
        if c.g[V1][0] == c.g[A1][0] {
            c.cycles += 1;
            bias = Addr(gp.wrapping_sub(GP_BIAS_BIG)).read_fpu(c);
        }
        abi::set_fpr(c, 23, vh);
        abi::set_fpr(c, 25, vx);
        abi::set_fpr(c, 26, vy);
        abi::set_fpr(c, 29, bias);
        abi::set_fpr(c, 21, vw);

        // Display width: x base = 32768 - 8 * width.
        c.cycles += 8;
        let method = set_ortho_display_method(c, gfx, 0x50);
        call_ptr(c, method, 0x0037_7518)?;
        let (x_off, _) = set_ortho_times8_to_float(c);
        c.cycles += 4;
        abi::set_fpr(c, 1, x_off);
        c.g[V1][0] = Addr(gfx).off(DISPLAY).lw(c);

        // Display height: y base = 32768 - 8 * height.
        c.cycles += 10;
        c.g[AT][0] = 0x4700_0000;
        let k32768 = FpuF32(0x4700_0000);
        abi::set_fpr(c, 0, k32768);
        let disp = c.g[V1][0] as u32;
        c.g[A0][0] = Addr(disp).off(0x58).lh(c);
        c.g[V0][0] = Addr(disp).off(0x5c).lw(c);
        let x_base = k32768 - x_off;
        abi::set_fpr(c, 20, x_base);
        c.g[A0][0] = sx(gfx.wrapping_add(c.g[A0][0] as u32));
        let method = c.g[V0][0] as u32;
        call_ptr(c, method, 0x0037_7560)?;
        let (y_off, halved) = set_ortho_times8_to_float(c);
        c.cycles += if halved { 3 } else { 4 };
        abi::set_fpr(c, 12, y_off);

        // Screen matrix and viewport quads.
        c.cycles += 67;
        let one = FpuF32::ONE;
        let sixteen = FpuF32(0x4180_0000);
        let depth = far - near;
        let x_scale = vw.div(width) * sixteen;
        let y_scale = vh.div(height) * sixteen;
        c.g[V1][0] = Addr(gfx).off(MODE).lw(c);
        Addr(sp0).off(0xc).write_fpu(c, depth);
        c.g[V0][0] = 0x31;
        let z_scale = (-bias).div(depth);
        let x0 = vx * sixteen;
        let y0 = vy * sixteen;
        let y_base = k32768 - y_off;
        let left_m = Addr(sp0).read_fpu(c);
        let top_m = Addr(sp0).off(4).read_fpu(c);
        let x_min = (x0 - x_scale * left_m) + x_base;
        let y_min = (y0 - y_scale * top_m) + y_base;
        let z_off = -far * z_scale;
        let x_max = (vx + vw) * sixteen + x_base;
        let y_max = (vy + vh) * sixteen + y_base;
        let z_far = z_scale * far + z_off;
        let z_near = z_scale * near + z_off;
        let vp_x = x0 + x_base;
        let vp_y = y0 + y_base;
        let m = Addr(gfx).off(SCREEN_MAT);
        m.write_fpu(c, x_scale);
        for o in [0x4, 0x8, 0xc, 0x10, 0x18, 0x1c, 0x20, 0x24, 0x2c] {
            m.off(o).sw(c, 0);
        }
        m.off(0x14).write_fpu(c, y_scale);
        m.off(0x28).write_fpu(c, z_scale);
        m.off(0x30).write_fpu(c, x_min);
        m.off(0x34).write_fpu(c, y_min);
        m.off(0x38).write_fpu(c, z_off);
        m.off(0x3c).write_fpu(c, one);
        let vmin = Addr(gfx).off(VIEWPORT_MIN);
        vmin.write_fpu(c, vp_x);
        vmin.off(4).write_fpu(c, vp_y);
        vmin.off(8).write_fpu(c, z_near);
        vmin.off(0xc).write_fpu(c, one);
        let vmax = Addr(gfx).off(VIEWPORT_MAX);
        vmax.write_fpu(c, x_max);
        vmax.off(4).write_fpu(c, y_max);
        vmax.off(8).write_fpu(c, z_far);
        vmax.off(0xc).write_fpu(c, one);
        Addr(gfx).off(MATS_READY).sw(c, 0);
        c.g[AT][0] = 0x4700_0000;
        for (r, v) in [
            (0, z_far),
            (1, z_near),
            (2, x_max),
            (3, y_max),
            (4, sixteen),
            (5, x_min),
            (6, y_min),
            (7, z_off),
            (8, y_base),
            (9, one),
            (10, vp_y),
            (11, vp_x),
        ] {
            abi::set_fpr(c, r, v);
        }
        // Depth constants for the mode (one on the stack, one kept in f31).
        let (depth_k, depth_far_k);
        if c.g[V1][0] != c.g[V0][0] {
            c.cycles += 3;
            depth_k = Addr(gp.wrapping_sub(GP_DEPTH)).read_fpu(c);
            depth_far_k = Addr(gp.wrapping_sub(GP_DEPTH_FAR)).read_fpu(c);
            abi::set_fpr(c, 3, depth_k);
        } else {
            c.cycles += 4;
            depth_k = Addr(gp.wrapping_sub(GP_DEPTH_BIG)).read_fpu(c);
            depth_far_k = Addr(gp.wrapping_sub(GP_DEPTH_FAR_BIG)).read_fpu(c);
            abi::set_fpr(c, 2, depth_k);
        }
        abi::set_fpr(c, 31, depth_far_k);
        Addr(sp0).off(8).write_fpu(c, depth_k);

        // Screen width in pixels; x centre of the viewport.
        c.cycles += 11;
        let two = FpuF32(0x4000_0000);
        c.g[AT][0] = 0x4000_0000;
        abi::set_fpr(c, 0, two);
        let method = set_ortho_display_method(c, gfx, 0x50);
        let inv_h2 = two.div(height);
        let inv_w2 = two.div(width);
        abi::set_fpr(c, 30, inv_h2);
        abi::set_fpr(c, 29, inv_w2);
        call_ptr(c, method, 0x0037_76d4)?;
        let screen_w = set_ortho_u64_to_float(c);
        abi::set_fpr(c, 1, screen_w);

        // Screen height in pixels; y centre of the viewport.
        c.cycles += 13;
        let half = FpuF32(0x3f00_0000);
        c.g[AT][0] = 0x3f00_0000;
        let half_screen_w = screen_w * half;
        let dx = vw * half - half_screen_w;
        let method = set_ortho_display_method(c, gfx, 0x58);
        let cx = dx + vx;
        abi::set_fpr(c, 1, half_screen_w);
        abi::set_fpr(c, 0, dx);
        abi::set_fpr(c, 20, cx);
        call_ptr(c, method, 0x0037_772c)?;
        let screen_h = set_ortho_u64_to_float(c);

        // Clip-space and projection matrices.
        c.cycles += 125;
        let minus_one = FpuF32(0xbf80_0000);
        let guard_w = FpuF32(0x4500_0000) - (cx.abs() + cx.abs());
        let half_vh = vh * half;
        let cy = (half_vh - screen_h * half) + vy;
        let guard_h = FpuF32(0x4500_0000) - (cy.abs() + cy.abs());
        let left_m = Addr(sp0).read_fpu(c);
        let top_m = Addr(sp0).off(4).read_fpu(c);
        let depth_m = Addr(sp0).off(0xc).read_fpu(c);
        let pixel = Addr(gp.wrapping_sub(GP_PIXEL_OFFSET)).read_fpu(c);
        let gx = vw.div(guard_w);
        let gy = vh.div(guard_h);
        let z_proj = (-(far + near)).div(depth_m);
        let off_x = (cx + pixel) - (left_m * vw).div(width);
        let off_y = (cy + pixel) - (top_m * vh).div(height);
        let two_over_depth = two.div(depth_m);
        let sx_clip = gx * inv_w2;
        let sy_clip = gy * inv_h2;
        let half_guard_w = guard_w * half;
        let half_guard_h = guard_h * half;
        let half_vw = vw * half;
        let depth_k_m = Addr(sp0).off(8).read_fpu(c);

        let p = Addr(gfx).off(PROJ_MAT);
        p.write_fpu(c, inv_w2);
        for o in [0x4, 0x8, 0xc, 0x10, 0x18, 0x1c, 0x20, 0x24, 0x2c] {
            p.off(o).sw(c, 0);
        }
        p.off(0x14).write_fpu(c, inv_h2);
        p.off(0x28).write_fpu(c, two_over_depth);
        p.off(0x30).write_fpu(c, minus_one);
        p.off(0x34).write_fpu(c, minus_one);
        p.off(0x38).write_fpu(c, z_proj);
        p.off(0x3c).write_fpu(c, one);
        // Viewport half sizes (0x58e0) and offsets (0x58f0) with the depths.
        let g = Addr(gfx);
        g.off(0x58e0).write_fpu(c, half_vw);
        g.off(0x58e4).write_fpu(c, half_vh);
        g.off(0x58e8).write_fpu(c, depth_k_m);
        g.off(0x58ec).sw(c, 0);
        g.off(0x58f0).write_fpu(c, off_x);
        g.off(0x58f4).write_fpu(c, off_y);
        g.off(0x58f8).write_fpu(c, depth_far_k);
        g.off(0x58fc).sw(c, 0);
        // Clip-space matrix (guard-band scaled ortho).
        let l = Addr(gfx).off(LOCAL_MAT);
        l.write_fpu(c, sx_clip);
        for o in [0x4, 0x8, 0xc, 0x10, 0x18, 0x1c, 0x20, 0x24, 0x2c] {
            l.off(o).sw(c, 0);
        }
        l.off(0x14).write_fpu(c, sy_clip);
        l.off(0x28).write_fpu(c, two_over_depth);
        l.off(0x30).write_fpu(c, -gx);
        l.off(0x34).write_fpu(c, -gy);
        l.off(0x38).write_fpu(c, z_proj);
        l.off(0x3c).write_fpu(c, one);
        // Clip quads: guard half sizes and offsets with the depths.
        g.off(0x5840).write_fpu(c, half_guard_w);
        g.off(0x5844).write_fpu(c, half_guard_h);
        g.off(0x5848).write_fpu(c, depth_k_m);
        g.off(0x584c).sw(c, 0);
        g.off(0x5850).write_fpu(c, off_x);
        g.off(0x5854).write_fpu(c, off_y);
        g.off(0x5858).write_fpu(c, depth_far_k);
        g.off(0x585c).sw(c, 0);

        // Registers at the call: SetScissorClamped(g, vx, vy, vw, vh).
        c.g[AT][0] = 0x4000_0000;
        for (r, v) in [
            (0, sy_clip),
            (1, off_y),
            (2, half_guard_w),
            (3, half_vw),
            (4, off_x),
            (5, half_guard_h),
            (6, depth_k_m),
            (7, sx_clip),
            (8, (left_m * vw).div(width)),
            (9, half),
            (10, -gy),
            (11, -gx),
            (12, vx),
            (13, vy),
            (14, vw),
            (15, vh),
            (16, z_proj),
            (17, two_over_depth),
            (18, one),
        ] {
            abi::set_fpr(c, r, v);
        }
        c.g[A0][0] = c.g[S0][0];
        SET_SCISSOR_CLAMPED.call(c, 0x0037_78ec)?;

        let gp = c.g[GP][0] as u32;
        let k5910 = Addr(gp.wrapping_sub(GP_5910)).read_fpu(c);
        let k5920 = Addr(gp.wrapping_sub(GP_5920)).read_fpu(c);
        let k592c = Addr(gp.wrapping_sub(GP_592C)).read_fpu(c);
        abi::set_fpr(c, 1, k5910);
        abi::set_fpr(c, 2, k5920);
        abi::set_fpr(c, 0, k592c);
        g.off(0x5910).write_fpu(c, k5910);
        g.off(0x592c).write_fpu(c, k592c);
        g.off(0x5920).write_fpu(c, k5920);
        g.off(0x5924).sw(c, 0);
        g.off(0x5928).sw(c, 0);

        frame.restore(c, S0, 0x20);
        frame.restore_ra(c, 0x10);
        for (f, off) in [
            (31, 0x88),
            (30, 0x80),
            (29, 0x78),
            (28, 0x70),
            (27, 0x68),
            (26, 0x60),
            (25, 0x58),
            (24, 0x50),
            (23, 0x48),
            (22, 0x40),
            (21, 0x38),
            (20, 0x30),
        ] {
            frame.restore_fpr(c, f, off);
        }
        frame.close(c);
        Ok(())
    })
}

// ---------------------------------------------------------------------------
// Irradiance_Rotate (0x389840, particle.cpp; assembly only in the reference).

/// FPU registers the function saves (f20..f31) and their frame slots.
pub(crate) const IRR_SAVED_FPRS: [(usize, u32); 12] = [
    (31, 0x98),
    (30, 0x90),
    (29, 0x88),
    (28, 0x80),
    (27, 0x78),
    (26, 0x70),
    (25, 0x68),
    (24, 0x60),
    (23, 0x58),
    (22, 0x50),
    (21, 0x48),
    (20, 0x40),
];

/// `void Irradiance_Rotate(Irradiance* irr, const float rot[3][3], int first,
/// int last)` (0x389840): rotate the irradiance's spherical-harmonic
/// coefficients by the 3x3 matrix `rot`, for the colour channels
/// `first..=last` (one float column per channel; the coefficient rows are
/// `irr + 0x10 .. irr + 0x90`, 16 bytes apart). The SH rotation is the
/// original's fully scheduled FPU sequence (207 cycles per channel), kept
/// instruction for instruction so every scratch FPR and the stack scratch
/// (`sp+0x00..0x34`: the matrix row 0 copy and products) end as it leaves
/// them.
pub fn irradiance_rotate(c: &mut Cpu) {
    c.cycles += 31;
    let frame = Frame::open(c, 0xa0);
    let s = sp(c);
    // t4 = irr, t5 = channel, t7 = last channel.
    c.g[T7][0] = c.g[A3][0];
    c.g[T5][0] = c.g[A2][0];
    c.g[T4][0] = c.g[A0][0];
    c.g[V0][0] = ((c.g[T7][0] as i64) < (c.g[T5][0] as i64)) as u64;
    for (f, off) in IRR_SAVED_FPRS {
        frame.save_fpr(c, f, off);
    }
    // The packed 3x3 matrix: rot[0][0], rot[0][1], rot[1][0] and rot[2][0]
    // to the stack, the other five in f27..f31.
    let m = c.g[A1][0] as u32;
    c.lwc1(0, m);
    c.lwc1(30, m.wrapping_add(0x20));
    c.swc1(0, s);
    c.lwc1(1, m.wrapping_add(0x4));
    c.swc1(1, s.wrapping_add(0x4));
    c.lwc1(2, m.wrapping_add(0xc));
    c.lwc1(29, m.wrapping_add(0x8));
    c.swc1(2, s.wrapping_add(0x8));
    c.lwc1(4, m.wrapping_add(0x18));
    c.lwc1(27, m.wrapping_add(0x10));
    c.lwc1(31, m.wrapping_add(0x14));
    c.swc1(4, s.wrapping_add(0xc));
    c.lwc1(28, m.wrapping_add(0x1c));
    if c.g[V0][0] == 0 {
        c.cycles += 1;
        loop {
            c.cycles += 207;
            // The channel's column in each coefficient row.
            let irr = c.g[T4][0] as u32;
            let col = (c.g[T5][0] as u32) << 2;
            c.g[V0][0] = sx(col);
            let row = |off: u32| irr.wrapping_add(off).wrapping_add(col);
            let (c10, c20, c30, c40) = (row(0x10), row(0x20), row(0x30), row(0x40));
            let (c50, c60, c70, c80, c90) = (row(0x50), row(0x60), row(0x70), row(0x80), row(0x90));
            c.g[A0][0] = sx(c10);
            c.g[A3][0] = sx(c20);
            c.g[A1][0] = sx(c30);
            c.g[T2][0] = sx(c40);
            c.g[T1][0] = sx(c50);
            c.g[T3][0] = sx(c60);
            c.g[V1][0] = sx(c70);
            c.g[T0][0] = sx(c80);
            c.g[A2][0] = sx(c90);
            c.g[T5][0] = sx((c.g[T5][0] as u32).wrapping_add(1));
            c.g[V0][0] = ((c.g[T7][0] as i64) < (c.g[T5][0] as i64)) as u64;
            c.lwc1(12, c20);
            c.lwc1(13, c10);
            c.add_s(5, 12, 12);
            c.lwc1(6, s.wrapping_add(0x8));
            c.lwc1(8, s.wrapping_add(0xc));
            c.swc1(5, s.wrapping_add(0x2c));
            c.lwc1(16, c40);
            c.lwc1(20, c60);
            c.mul_s(6, 16, 6);
            c.mul_s(8, 16, 8);
            c.lwc1(7, s.wrapping_add(0x4));
            c.mul_s(11, 20, 28);
            c.lwc1(19, s);
            c.swc1(6, s.wrapping_add(0x18));
            c.mul_s(26, 5, 7);
            c.mul_s(2, 6, 7);
            c.lwc1(9, c30);
            c.swc1(8, s.wrapping_add(0x20));
            c.mul_s(16, 16, 19);
            c.lwc1(10, c50);
            c.add_s(22, 13, 13);
            c.swc1(11, s.wrapping_add(0x24));
            c.mul_s(4, 26, 27);
            c.mul_s(25, 10, 19);
            c.lwc1(15, s.wrapping_add(0x8));
            c.lwc1(0, c80);
            c.mul_s(1, 8, 7);
            c.lwc1(19, s.wrapping_add(0x4));
            c.mul_s(3, 22, 15);
            c.swc1(0, s.wrapping_add(0x14));
            c.add_s(2, 2, 4);
            c.lwc1(5, s.wrapping_add(0x24));
            c.mul_s(0, 12, 19);
            c.lwc1(6, c70);
            c.add_s(11, 9, 9);
            c.lwc1(17, c90);
            c.mul_s(8, 5, 29);
            c.swc1(6, s.wrapping_add(0x10));
            c.mul_s(4, 25, 31);
            c.mul_s(6, 9, 29);
            c.lwc1(7, s.wrapping_add(0xc));
            c.add_s(1, 1, 8);
            c.lwc1(15, s.wrapping_add(0x18));
            c.mul_s(0, 0, 19);
            c.lwc1(8, s.wrapping_add(0x8));
            c.mul_s(6, 6, 29);
            c.mul_s(24, 10, 7);
            c.mul_s(3, 3, 7);
            c.mul_s(23, 11, 29);
            c.mul_s(7, 16, 28);
            c.add_s(2, 2, 4);
            c.mul_s(21, 20, 27);
            c.lwc1(4, s);
            c.mul_s(10, 10, 8);
            c.add_s(0, 0, 6);
            c.lwc1(6, s.wrapping_add(0x4));
            c.mul_s(5, 15, 28);
            c.mul_s(8, 23, 31);
            c.mul_s(22, 22, 4);
            c.add_s(1, 1, 7);
            c.mul_s(20, 20, 6);
            c.mul_s(14, 10, 31);
            c.mul_s(18, 16, 6);
            c.mul_s(4, 21, 31);
            c.lwc1(6, s);
            c.mul_s(7, 12, 27);
            c.mul_s(15, 24, 31);
            c.add_s(3, 3, 5);
            c.mul_s(11, 11, 31);
            c.mul_s(5, 9, 30);
            c.add_s(2, 2, 8);
            c.mul_s(19, 25, 30);
            c.mul_s(8, 13, 6);
            c.add_s(4, 4, 14);
            c.mul_s(7, 7, 27);
            c.mul_s(9, 9, 31);
            c.mul_s(6, 21, 29);
            c.add_s(3, 3, 15);
            c.mul_s(11, 11, 30);
            c.mul_s(15, 24, 30);
            c.mul_s(5, 5, 30);
            c.add_s(1, 1, 19);
            c.add_s(4, 4, 7);
            c.lwc1(19, s.wrapping_add(0xc));
            c.mul_s(9, 9, 31);
            c.lwc1(7, s.wrapping_add(0x8));
            c.add_s(3, 3, 11);
            c.add_s(2, 2, 6);
            c.lwc1(11, s.wrapping_add(0x24));
            c.lwc1(6, s);
            c.add_s(5, 5, 15);
            c.mul_s(14, 22, 19);
            c.lwc1(15, s.wrapping_add(0x20));
            c.add_s(4, 4, 9);
            c.mul_s(19, 11, 31);
            c.lwc1(9, s.wrapping_add(0x18));
            c.mul_s(8, 8, 6);
            c.add_s(0, 0, 18);
            c.mul_s(11, 15, 28);
            c.mul_s(15, 20, 31);
            c.mul_s(6, 13, 7);
            c.mul_s(9, 9, 27);
            c.mul_s(7, 20, 29);
            c.add_s(3, 3, 19);
            c.add_s(0, 0, 8);
            c.lwc1(19, s.wrapping_add(0xc));
            c.lwc1(8, s.wrapping_add(0x8));
            c.add_s(5, 5, 11);
            c.swc1(9, s.wrapping_add(0x1c));
            c.add_s(2, 2, 15);
            c.mul_s(12, 12, 28);
            c.lwc1(15, s.wrapping_add(0x24));
            c.mul_s(11, 10, 30);
            c.add_s(0, 0, 7);
            c.mul_s(25, 25, 29);
            c.mul_s(10, 10, 29);
            c.mul_s(15, 15, 30);
            c.mul_s(12, 12, 28);
            c.mul_s(13, 13, 19);
            c.add_s(0, 0, 25);
            c.swc1(15, s.wrapping_add(0x28));
            c.mul_s(6, 6, 8);
            c.add_s(3, 3, 11);
            c.add_s(2, 2, 10);
            c.lwc1(11, s.wrapping_add(0x2c));
            c.add_s(1, 1, 14);
            c.lwc1(10, s.wrapping_add(0x20));
            c.mul_s(26, 26, 28);
            c.swc1(0, c10);
            c.add_s(5, 5, 12);
            c.lwc1(0, s.wrapping_add(0x4));
            c.mul_s(13, 13, 19);
            c.add_s(4, 4, 6);
            c.lwc1(19, s.wrapping_add(0x14));
            c.mul_s(22, 22, 8);
            c.add_s(1, 1, 26);
            c.lwc1(8, s.wrapping_add(0x1c));
            c.mul_s(23, 23, 30);
            c.mul_s(21, 21, 30);
            c.mul_s(16, 16, 27);
            c.add_s(5, 5, 13);
            c.mul_s(7, 10, 27);
            c.add_s(4, 4, 8);
            c.lwc1(10, s.wrapping_add(0x10));
            c.add_s(1, 1, 23);
            c.mul_s(24, 24, 29);
            c.add_s(3, 3, 21);
            c.mul_s(12, 11, 27);
            c.add_s(5, 5, 15);
            c.lwc1(11, s.wrapping_add(0x8));
            c.add_s(2, 2, 16);
            c.swc1(4, c20);
            c.add_s(3, 3, 7);
            c.add_s(1, 1, 24);
            c.swc1(5, c30);
            c.mul_s(20, 20, 30);
            c.mul_s(9, 19, 0);
            c.lwc1(15, s);
            c.mul_s(7, 19, 28);
            c.add_s(2, 2, 22);
            c.mul_s(19, 19, 27);
            c.add_s(1, 1, 20);
            c.swc1(2, c40);
            c.mul_s(6, 17, 29);
            c.swc1(19, s.wrapping_add(0x30));
            c.mul_s(8, 17, 31);
            c.swc1(1, c50);
            c.mul_s(0, 10, 11);
            c.lwc1(1, s.wrapping_add(0xc));
            c.mul_s(12, 12, 28);
            c.mul_s(17, 17, 30);
            c.add_s(6, 6, 9);
            c.mul_s(4, 10, 15);
            c.mul_s(1, 10, 1);
            c.add_s(0, 0, 8);
            c.add_s(3, 3, 12);
            c.add_s(17, 17, 7);
            c.swc1(1, s.wrapping_add(0x34));
            c.add_s(6, 6, 4);
            c.add_s(0, 0, 19);
            c.swc1(3, c60);
            c.add_s(17, 17, 1);
            c.swc1(6, c70);
            c.swc1(0, c80);
            // (In the original this last store sits after the loop test,
            // in the branch delay slot.)
            c.swc1(17, c90);
            if c.g[V0][0] != 0 {
                break;
            }
            if event_due(c) {
                deliver_event_here(c, 0x0038_98c0);
            }
        }
    }
    c.cycles += 14;
    for (f, off) in IRR_SAVED_FPRS {
        frame.restore_fpr(c, f, off);
    }
    frame.close(c);
}

// ---------------------------------------------------------------------------
// Irradiance_AddDirectionalScaled (0x389308, particle.cpp)

/// gp-relative `.lit4`: the spherical-harmonic basis constants (band 0,
/// band 1 and the five band-2 terms, with their per-term scales).
pub(crate) const GP_SH_CONSTS: [(usize, u32); 11] = [
    (30, 0x272c),
    (29, 0x2728),
    (28, 0x2724),
    (27, 0x2720),
    (18, 0x271c),
    (17, 0x2718),
    (26, 0x2714),
    (25, 0x2710),
    (24, 0x270c),
    (23, 0x2708),
    (22, 0x2704),
];

/// The callee-saved FPU registers the function uses, with their frame
/// slots.
pub(crate) const SH_SAVED: [(usize, u32); 11] = [
    (20, 0x30),
    (30, 0x80),
    (29, 0x78),
    (28, 0x70),
    (27, 0x68),
    (26, 0x60),
    (25, 0x58),
    (24, 0x50),
    (23, 0x48),
    (22, 0x40),
    (21, 0x38),
];

/// `void Irradiance_AddDirectionalScaled(SH9Color* sh, const float rgb[3],
/// float scale, float x, float y, float z)` (0x389308): adds a directional
/// light of colour `rgb * scale` from direction (x, y, z) to the 9-term
/// spherical-harmonic irradiance `sh` (per channel: band 0 at +0x00,
/// band 2 terms at +0x10..+0x60 in 0x10 strides, band 1 at +0x70/+0x80/
/// +0x90). The per-channel terms are spilled to the frame as the original
/// does (0x00..0x20); every FPU temporary is left as the original leaves
/// it. Leaf.
pub fn irradiance_add_directional_scaled(c: &mut Cpu) {
    c.cycles += 40;
    // f0 = 3 z^2 - 1 (f19), f20 = x^2 - y^2; f16 = x.
    c.g[AT][0] = 0x4040_0000;
    c.mtc1(AT, 0);
    c.mov_s(16, 13);
    c.mul_s(2, 16, 16);
    let frame = Frame::open(c, 0x90);
    c.mul_s(0, 15, 0);
    c.g[AT][0] = 0x3f80_0000;
    c.mtc1(AT, 3);
    c.mul_s(1, 14, 14);
    for (f, off) in SH_SAVED {
        frame.save_fpr(c, f, off);
    }
    c.g[T0][0] = c.g[A0][0]; // sh
    c.mul_s(0, 15, 0);
    c.sub_s(20, 2, 1);
    c.g[A3][0] = c.g[T0][0]; // band 0 cursor
    c.sub_s(19, 0, 3);
    c.g[T1][0] = c.g[A1][0]; // rgb cursor
    c.g[T2][0] = 0; // channel
    c.g[A2][0] = sx(r32(c, A3).wrapping_add(0x60)); // band 2 cursor
    c.mov_s(21, 12); // scale
    for (f, off) in GP_SH_CONSTS {
        c.lwc1(f, r32(c, GP).wrapping_sub(off));
    }
    loop {
        c.cycles += 81;
        let sp = frame.at(c, 0);
        c.lwc1(0, r32(c, T1));
        c.g[V0][0] = sx(r32(c, T2) << 2);
        c.lwc1(3, r32(c, A3));
        c.g[V1][0] = sx(r32(c, T0).wrapping_add(0x70));
        c.mul_s(0, 0, 21); // colour * scale
        c.g[V1][0] = sx(r32(c, V1).wrapping_add(r32(c, V0)));
        c.g[A0][0] = sx(r32(c, T0).wrapping_add(0x80));
        c.g[A1][0] = sx(r32(c, T0).wrapping_add(0x90));
        c.g[A0][0] = sx(r32(c, A0).wrapping_add(r32(c, V0)));
        c.g[A1][0] = sx(r32(c, A1).wrapping_add(r32(c, V0)));
        c.mul_s(4, 0, 30);
        c.g[T2][0] = sx(r32(c, T2).wrapping_add(1));
        c.g[T1][0] = sx(r32(c, T1).wrapping_add(4));
        c.g[V0][0] = ((c.g[T2][0] as i64) < 3) as u64;
        c.swc1(4, sp);
        c.mul_s(4, 0, 29);
        c.lwc1(2, sp);
        c.mul_s(11, 4, 16);
        c.mul_s(12, 4, 14);
        c.mul_s(13, 4, 15);
        c.mul_s(4, 0, 28);
        c.swc1(11, sp + 0xc);
        c.mul_s(2, 2, 25);
        c.swc1(12, sp + 0x4);
        c.swc1(13, sp + 0x8);
        c.mul_s(11, 11, 17);
        c.mul_s(6, 4, 16);
        c.mul_s(8, 4, 14);
        c.mul_s(4, 0, 27);
        c.mul_s(9, 6, 15);
        c.mul_s(8, 8, 15);
        c.mul_s(7, 4, 19);
        c.mul_s(4, 0, 26);
        c.swc1(9, sp + 0x1c);
        c.mul_s(6, 6, 14);
        c.swc1(8, sp + 0x14);
        c.mul_s(1, 7, 24);
        c.swc1(7, sp + 0x18);
        c.mul_s(0, 4, 20);
        c.swc1(6, sp + 0x10);
        c.mul_s(7, 7, 22);
        c.sub_s(2, 2, 1);
        c.swc1(0, sp + 0x20);
        c.mul_s(10, 0, 23);
        c.mul_s(6, 6, 18);
        c.add_s(3, 3, 2);
        c.mul_s(9, 9, 18);
        c.mul_s(8, 8, 18);
        c.swc1(3, r32(c, A3)); // band 0
        c.mul_s(12, 12, 17);
        c.mul_s(13, 13, 17);
        c.g[A3][0] = sx(r32(c, A3).wrapping_add(4));
        // Band 2: the five terms of this channel (0x10 strides).
        let b2 = r32(c, A2);
        c.lwc1(2, b2.wrapping_sub(0x50));
        c.lwc1(4, b2.wrapping_sub(0x40));
        c.lwc1(5, b2.wrapping_sub(0x30));
        c.add_s(2, 2, 10);
        c.lwc1(3, b2.wrapping_sub(0x20));
        c.sub_s(4, 4, 10);
        c.lwc1(1, b2.wrapping_sub(0x10));
        c.add_s(5, 5, 7);
        c.lwc1(0, b2);
        c.add_s(3, 3, 6);
        c.add_s(1, 1, 9);
        c.swc1(2, b2.wrapping_sub(0x50));
        c.add_s(0, 0, 8);
        c.swc1(4, b2.wrapping_sub(0x40));
        c.swc1(5, b2.wrapping_sub(0x30));
        c.swc1(3, b2.wrapping_sub(0x20));
        c.swc1(1, b2.wrapping_sub(0x10));
        c.swc1(0, b2);
        c.g[A2][0] = sx(b2.wrapping_add(4));
        // Band 1: x, y, z terms.
        for (reg, term) in [(V1, 11), (A0, 12), (A1, 13)] {
            let a = r32(c, reg);
            let f = if term == 12 { 1 } else { 0 };
            c.lwc1(f, a);
            c.add_s(f, f, term);
            c.swc1(f, a);
        }
        if c.g[V0][0] == 0 {
            break;
        }
        if event_due(c) {
            deliver_event_here(c, 0x0038_93a8);
        }
    }
    c.cycles += 13;
    for (f, off) in SH_SAVED {
        frame.restore_fpr(c, f, off);
    }
    frame.close(c);
}

