        c.cycles += 2;
        let none = (c.g[T5][0] as i64) <= 0;
        c.g[A1][0] = 0;
        if !none {
            bezier_fill_free_list(c, 0x0037_3bb0, T5, 0x1dc, 0x1d0);
        }
        c.cycles += 2;
        let none = (c.g[T6][0] as i64) <= 0;
        c.g[A1][0] = 0;
