                clear(c, vt, 0x500);
                c.bus.write32(this + 0x10d8, vt);
                vtable_2(c, vt, &[(0x3d8, 0, FAKE), (0x20, 0, FAKE + 0x10)]);
                c.g[A0][0] = sx(this);
                let _ = seed;
