    /// Dma_SendGifNormal: a GIF packet of 0..=16 empty end-of-packet GIF
    /// tags in main memory (or a scratchpad address above 0x6fffffff), the
    /// `MSKPATH3` quadword at 0x44b430, and every combination of the wait
    /// flags (with the channel busy or idle beforehand: a first transfer
    /// started by the setup).
    #[test]
    fn dma_send_gif_normal_matches() {
        check(
            ee::s12::f_00371940__generated,
            dma_send_gif_normal,
            300,
            &|c, seed| {
                let mut r = Rng(0x0037_1940 ^ (seed as u64) << 13);
                scramble(c, &mut r);
                crate::difftest::put_words(c, GIF_SEND_VIF_PREFIX, &[0x0600_0000, 0, 0, 0]);
                let qwc = r.next_u32() % 17;
                for i in 0..16 {
                    crate::difftest::put_vec(c, DATA + 0x10 * i, [0x8000, 0, 0, 0]);
                    c.bus.spr[0x10 * i as usize..0x10 * i as usize + 4]
                        .copy_from_slice(&0x8000u32.to_le_bytes());
                }
                let madr = if seed % 4 == 0 {
                    0x7000_0000 | (r.next_u32() % 4) << 4
                } else {
                    DATA
                };
                c.g[A0][0] = sx(madr);
                c.g[A1][0] = sx(qwc);
                c.g[A2][0] = sx(r.next_u32() % 8 | r.next_u32() & 0xff00);
                if seed % 3 == 0 {
                    // A transfer in flight: the channel is busy at the start.
                    c.sw(GIF_MADR, DATA as u64);
                    c.sw(GIF_QWC, 16);
                    c.sw(GIF_CHCR, 0x101);
                }
                c.pc = 0x0037_1940;
            },
        );
    }

    /// `DeferMan_ResetFrame`: a DeferMan at DATA with random words in the
    /// fields it touches, a random template record, the scratchpad stream's
    /// free pointer leaving 0x400..0x4000 free bytes and random scratchpad
    /// contents. The real InvalidDCache, EA_MemSet and SprStream_Download
    /// run (DMA from the scratchpad, waiting).
    #[test]
    fn defer_man_reset_frame_matches() {
        const DM: u32 = DATA;
        crate::difftest::check(
            ee::s12::f_00362cc8__generated,
            defer_man_reset_frame,
            200,
            &|c, seed| {
                let mut r = Rng(0x0036_2cc8 ^ (seed as u64) << 17);
                crate::difftest::scramble(c, &mut r);
                c.g[GP][0] = GAME_GP as u64;
                c.pc = 0x0036_2cc8;
                let free = 0x400 + (r.next_u32() % 0x3c1) * 0x10;
                c.bus.write32(GAME_GP + GP_SPR_FREE, 0x7000_4000 - free);
                for i in 0..0x1000 {
                    c.bus.spr[i * 4..i * 4 + 4].copy_from_slice(&r.next_u32().to_le_bytes());
                }
                for o in [
                    DEFER_COUNT,
                    DEFER_RESET_FROM,
                    DEFER_RESET_TO,
                    DEFER_57494,
                    DEFER_67CA4,
                ] {
                    c.bus.write32(DM + o, r.next_u32());
                }
                fill(c, &mut r, DM + DEFER_BUF_A, 0x200);
                fill(c, &mut r, DM + DEFER_RECORD, 8);
                fill(c, &mut r, DEFER_RECORD_TEMPLATE, 5);
                for o in [DEFER_69CC0, DEFER_69CC4, DEFER_69CC8, DEFER_6AED0] {
                    c.bus.write32(DM + DEFER_HI + o, r.next_u32());
                }
                c.g[A0][0] = sx(DM);
            },
        );
    }

    /// BezierPatchCache_TessUV2: sizes -1..7 (none, a single vertex, grids),
    /// 8-byte aligned and word-aligned rectangles and outputs.
    #[test]
    fn bezier_patch_cache_tess_uv2_matches() {
        use crate::difftest::{scramble, Rng};
        check(
            ee::s12::f_00374440__generated,
            bezier_patch_cache_tess_uv2,
            300,
            &|c, seed| {
                let mut r = Rng(0x37_4440 ^ (seed as u64) << 20);
                scramble(c, &mut r);
                c.pc = 0x0037_4440;
                let level = r.next_u32() % 4;
                let this = DATA;
                for k in 0..4 {
                    c.bus.write32(this + BPC_TESS_N + 4 * k, r.next_u32());
                }
                let n = (seed % 9) as i32 - 1;
                c.bus.write32(this + BPC_TESS_N + 4 * level, n as u32);
                let rect = DATA + 0x400 + 4 * (seed / 9 % 2);
                for k in 0..4 {
                    c.bus.write32(
                        rect + 0x10 + 4 * k,
                        if seed % 7 == 0 {
                            r.edge_f32()
                        } else {
                            r.f32(10.0)
                        },
                    );
                }
                c.g[A0][0] = sx(this);
                c.g[A1][0] = sx(rect);
                c.g[A2][0] = sx(DATA + 0x1000 + 4 * (seed / 18 % 2));
                c.g[A3][0] = level as u64 | (r.next_u32() as u64) << 32;
            },
        );
    }

    /// VfxTube_UpdateColorTable: colour unchanged (each channel equal up to
    /// the first differing one) or changed (the whole table rewritten).
    #[test]
    fn vfx_tube_update_color_table_matches() {
        check(
            ee::s12::f_003725b0__generated,
            vfx_tube_update_color_table,
            200,
            &|c, seed| {
                let mut r = Rng(0x3725_b0 ^ (seed as u64) << 8);
                scramble(c, &mut r);
                c.g[GP][0] = GAME_GP as u64;
                c.pc = 0x0037_25b0;
                let gp = GAME_GP;
                // Ints, small enough to be exact as floats.
                let ints = [r.next_u32() % 256, r.next_u32() % 256, r.next_u32() % 256];
                // How many leading channels already match (3 = no update).
                let matching = seed % 4;
                for i in 0..3u32 {
                    c.bus.write32(gp + TUBE_COLOR_INT + 4 * i, ints[i as usize]);
                    let last = if i < matching {
                        ints[i as usize] as f32
                    } else {
                        ints[i as usize] as f32 + 1.0
                    };
                    c.bus.write32(gp + TUBE_COLOR_LAST + 4 * i, last.to_bits());
                }
            },
        );
    }

