    pub(crate) const RINIT_GATE: u32 = DATA + 0x3000;

    pub(crate) const RINIT_MAGIC: u32 = 0x5249_4e54;

    /// Bump pointer of the allocation fakes.
    pub(crate) const RINIT_BUMP: u32 = DATA + 0x3008;

